NAME = 'CzeCSP: Czech Český studijní překlad'
BOOK = 'Matthew'

CHAPTERS = {
    1: {
        1: 'Rodokmen Ježíše Krista, syna Davidova, syna Abrahamova.',
        2: 'Abraham zplodil Izáka, Izák zplodil Jákoba, Jákob zplodil Judu a jeho bratry,',
        3: 'Juda zplodil Farese a Záru z Támary, Fares zplodil Chesróma, Chesróm zplodil Arama.',
        4: 'Aram zplodil Amínadaba, Amínadab zplodil Naasona, Naason zplodil Salmóna,',
        5: 'Salmón zplodil Bóaza z Rachaby, Bóaz zplodil Obéda z Rút, Obéd zplodil Isaje,',
        6: 'Isaj zplodil Davida krále. [Král] David zplodil Šalomouna z ženy Uriášovy,',
        7: 'Šalomoun zplodil Roboáma, Roboám zplodil Abiu, Abia zplodil Asafa,',
        8: 'Asaf zplodil Jóšafata, Jóšafat zplodil Jórama, Jóram zplodil Uziáše,',
        9: 'Uziáš zplodil Jótama, Jótam zplodil Achaza, Achaz zplodil Ezechiáše,',
        10: 'Ezechiáš zplodil Manasese, Manases zplodil ⌈Amose, Amos⌉ zplodil Joziáše,',
        11: 'Joziáš zplodil Jechoniáše a jeho bratry za babylonského zajetí.',
        12: 'Po babylonském zajetí Jechoniáš zplodil Salathiela, Salathiel zplodil Zorobabela,',
        13: 'Zorobabel zplodil Abiuda, Abiud zplodil Eljakima, Eljakim zplodil Azóra.',
        14: 'Azór zplodil Sádoka, Sádok zplodil Achima, Achim zplodil Eliuda,',
        15: 'Eliud zplodil Eleazara, Eleazar zplodil Mattana, Mattan zplodil Jákoba.',
        16: 'Jákob zplodil Josefa, muže Marie, z níž se narodil Ježíš řečený Kristus.',
        17: 'Všech pokolení od Abrahama do Davida bylo tedy čtrnáct, od Davida po babylonské zajetí čtrnáct a od babylonského zajetí do Krista čtrnáct.',
        18: 'S narozením Ježíše Krista to bylo takto: Jeho matka Marie byla zasnoubena Josefovi. Dříve než se sešli, zjistilo se, ⌈že je těhotná⌉ z Ducha Svatého.',
        19: 'Její muž Josef byl ⌈spravedlivý, ale nechtěl⌉ ji vystavit hanbě; rozhodl se propustit ji tajně.',
        20: 'Když to rozvážil, hle, Pánův anděl se mu ukázal ve snu a řekl: „Josefe, synu Davidův, neboj se přijmout Marii, svou ženu; neboť co v ní bylo počato, je z Ducha Svatého.',
        21: 'Porodí syna a ⌈dáš mu jméno⌉ Ježíš, neboť on vysvobodí svůj lid z jeho hříchů.“',
        22: 'To všechno se událo, aby se naplnilo, co bylo řečeno od Pána skrze proroka:',
        23: 'Hle, ta panna otěhotní a porodí syna a dají mu jméno Immanuel, což v překladu znamená: Bůh s námi.',
        24: 'Když se Josef probudil ze spánku, učinil, jak mu nařídil Pánův anděl, a přijal svou ženu.',
        25: 'Ale nepoznal ji, dokud neporodila [svého prvorozeného] syna. A dal mu jméno Ježíš.',
    },
    2: {
        1: 'Když se Ježíš narodil v judském Betlémě za dnů krále Heroda, hle, mágové od východu přišli do Jeruzaléma',
        2: 'a říkali: „Kde je ten narozený král Židů? Spatřili jsme jeho hvězdu, ⌈když vycházela⌉, a přišli jsme se mu poklonit.“',
        3: 'Když to uslyšel král Herodes, ⌈znepokojil se⌉ a s ním celý Jeruzalém.',
        4: 'Shromáždil všechny velekněze a ⌈učitele Zákona⌉ z lidu a vyptával se jich, kde se má Mesiáš narodit.',
        5: 'Oni mu řekli: „V judském Betlémě; neboť tak je napsáno skrze proroka:',
        6: 'A ty, Betléme, země Judova, vůbec nejsi nejmenší mezi vladaři Judy, neboť z tebe vyjde vůdce, který bude pást můj lid, Izrael. “',
        7: 'Tehdy Herodes tajně zavolal mágy a podrobně se jich vyptal na ⌈čas, kdy se hvězda ukazovala⌉,',
        8: 'poslal je do Betléma a řekl: „Jděte a pečlivě se vyptejte na to dítě; a jakmile je naleznete, oznamte mi to, abych se mu i já přišel poklonit.“',
        9: 'Vyslechli krále a vyšli. A hle, hvězda, kterou spatřili, ⌈když vycházela⌉, šla před nimi, až se zastavila nad místem, kde bylo to dítě.',
        10: 'Když spatřili hvězdu, nesmírně se zaradovali.',
        11: 'Vešli do domu a uviděli dítě s Marií, jeho matkou. Padli na zem a poklonili se mu. Pak otevřeli své pokladnice a obětovali mu dary: zlato, kadidlo a myrhu.',
        12: 'A poněvadž dostali ve snu pokyn, aby se k Herodovi nevraceli, odebrali se do své země jinou cestou.',
        13: 'Když odešli, hle, ukázal se Josefovi ve snu Pánův anděl a řekl: „Vstaň, vezmi dítě a jeho matku, uteč do Egypta a buď tam, dokud ti neřeknu, protože Herodes bude dítě hledat, aby je zahubil.“',
        14: 'On tedy vstal, vzal v noci dítě i jeho matku a odešel do Egypta.',
        15: 'A byl tam až do Herodovy smrti, aby se naplnilo,co bylo řečeno od Pána skrze proroka: Z Egypta jsem povolal svého syna.',
        16: 'Když Herodes uviděl, že ho mágové oklamali, velice se rozlítil a dal pobít všechny chlapce v Betlémě i v celém jeho okolí, od dvouletých níže, podle času, který vyzvěděl od mágů.',
        17: 'Tehdy se naplnilo,co bylo řečeno skrze proroka Jeremjáše:',
        18: 'Hlas v Ráma bylo slyšet, [nářek a] pláč a velké bědování; Ráchel oplakává své děti a nechce se dát utěšit, protože jich není.',
        19: 'Když Herodes zemřel, hle, Pánův anděl se ukázal ve snu Josefovi v Egyptě',
        20: 'a řekl: „Vstaň, vezmi dítě a jeho matku a jdi do země izraelské, neboť ti, kteří ⌈ukládali dítěti o život⌉, již zemřeli.“',
        21: 'On tedy vstal, vzal dítě a jeho matku a vešel do izraelské země.',
        22: 'Když však uslyšel, že v Judsku kraluje místo svého otce Heroda Archelaos, bál se tam odejít. Na pokyn ve snu odešel do oblasti Galileje.',
        23: 'I přišel a usadil se ve městě zvaném Nazaret, aby se naplnilo, co bylo řečeno skrze proroky: Bude nazýván Nazaretský.',
    },
    3: {
        1: 'V těch dnech přichází Jan Křtitel hlásající v judské pustině:',
        2: '„⌈Čiňte pokání,⌉ neboť se přiblížilo království Nebes.“',
        3: 'To je ten, o němž bylo řečeno skrze proroka Izaiáše: Hlas volajícího v pustině: Připravte Pánovu cestu, vyrovnávejte jeho stezky!',
        4: 'Sám Jan pak měl na sobě oděv z velbloudí srsti a kolem beder kožený pás a jeho potravou byly kobylky a med divokých včel.',
        5: 'Tehdy vycházel k němu Jeruzalém a celé Judsko i celé okolí Jordánu',
        6: 'a dávali se od něho pokřtít v [řece] Jordánu, vyznávajíce své hříchy.',
        7: 'Když však uviděl, jak mnozí farizeové a saduceové přicházejí k jeho křtu, řekl jim: „⌈Plemeno zmijí⌉! Kdo vám ukázal, jak utéci před nadcházejícím hněvem?',
        8: 'Vydávejte tedy ovoce ⌈svědčící o⌉ pokání.',
        9: 'A nedomnívejte se, že si můžete říkat: Náš otec je Abraham. Neboť vám pravím, že Bůh může Abrahamovi vzbudit děti z těchto kamenů.',
        10: 'Sekera je už přiložena ke kořeni stromů; každý strom, který nenese dobré ovoce, bude vyťat a hozen do ohně.',
        11: 'Já vás křtím ve vodě k pokání; ale ten, který přichází za mnou, je silnější než já; jemu nejsem hoden ani nést sandály. On vás bude křtít ⌈v Duchu Svatém a ohni⌉.',
        12: 'V jeho ruce je lopata; i pročistí svůj mlat a shromáždí svou pšenici do sýpky, plevy však bude pálit ohněm neuhasitelným.“',
        13: 'Tehdy Ježíš přišel z Galileje k Jordánu za Janem, aby byl od něho pokřtěn.',
        14: 'Ale Jan se mu v tom ⌈snažil zabránit⌉ a říkal: „Já bych měl být pokřtěn od tebe, a ty přicházíš ke mně?“',
        15: 'Ježíš mu odpověděl: „Nech to nyní; neboť takto je třeba, abychom naplnili všechnu spravedlnost.“On ho tedy nechal.',
        16: 'Když byl Ježíš pokřtěn, vystoupil hned z vody. A hle, otevřela se [mu] nebesa a spatřil Ducha Božího, jak sestupuje jako holubice a přichází na něho.',
        17: 'A hle, ozval se hlas z nebes, který říkal: „Toto je ⌈můj Syn, Milovaný⌉, v němž ⌈jsem nalezl zalíbení⌉.“',
    },
    4: {
        1: 'Tehdy Duch Ježíše vyvedl do pustiny, aby byl pokoušen od Ďábla.',
        2: 'A když se postil čtyřicet dní a čtyřicet nocí, nakonec vyhladověl.',
        3: 'Tu přistoupil Pokušitel a řekl mu: „Jsi–li Syn Boží, řekni, ať se z těchto kamenů stanou chleby.“',
        4: 'On však ⌈na to⌉ řekl: „Je napsáno: Člověk nebude živ jen chlebem, ale každým slovem, které vychází z Božích úst. “',
        5: 'Potom ho Ďábel vzal do svatého města, postavil ho na okraj střechy chrámu',
        6: 'a řekl mu: „Jsi–li Syn Boží, vrhni se dolů; vždyť je napsáno: Svým andělům přikáže o tobě, a na rukou tě ponesou, abys snad nenarazil nohou na kámen. “',
        7: 'Ježíš mu řekl: „Je také napsáno: Nebudeš pokoušet Pána, svého Boha. “',
        8: 'Pak ho Ďábel vzal na velmi vysokou horu a ukázal mu všechna království světa a jejich slávu.',
        9: 'A řekl mu: „Toto všechno ti dám, jestliže padneš na zem a pokloníš se mi.“',
        10: 'Tu mu Ježíš řekl: „Odejdi, Satane. Vždyť je napsáno: Pánu, svému Bohu, se budeš klanět a jeho jediného uctívat. “',
        11: 'A tehdy ho Ďábel opustil. A hle, andělé přistoupili a sloužili mu.',
        12: 'Když [Ježíš] uslyšel, že byl Jan uvězněn, odebral se do Galileje.',
        13: 'Opustil Nazaret, šel a usadil se v Kafarnaum, které je u moře, v oblastech Zabulón a Neftalí,',
        14: 'aby se naplnilo, co bylo řečeno skrze proroka Izaiáše:',
        15: 'Země Zabulón a země Neftalí, cestou u moře, za Jordánem -- Galilea pohanů;',
        16: 'lid sedící v temnotě uviděl veliké světlo, těm, kteří seděli v krajině a stínu smrti, vzešlo světlo.',
        17: 'Od té chvíle začal Ježíš hlásat a říkat: „Čiňte pokání, neboť se přiblížilo království Nebes.“',
        18: 'Když se procházel podél Galilejského moře, uviděl dva bratry, Šimona zvaného Petr a jeho bratra Ondřeje, jak do moře vrhají kruhovou síť; byli totiž rybáři.',
        19: 'Řekl jim: „Pojďte za mnou a učiním z vás rybáře lidí.“',
        20: 'Oni hned opustili sítě a následovali ho.',
        21: 'A když odtamtud poodešel, uviděl jiné dva bratry, Jakuba, syna Zebedeova, a jeho bratra Jana, jak v lodi se svým otcem Zebedeem spravují své sítě. I povolal je.',
        22: 'Oni ihned opustili loď i svého otce a následovali ho.',
        23: 'Procházel celou Galilejí, učil v jejich synagogách, hlásal ⌈evangelium království⌉ a uzdravoval každou nemoc a každou slabost v lidu.',
        24: 'Pověst o něm se roznesla po celé Sýrii. Přinesli k němu všechny nemocné, kteří byli sužováni rozličnými nemocemi a trápeními, démonizované, náměsíčné i ochrnuté a on je uzdravil.',
        25: 'Šly za ním veliké zástupy z Galileje, Dekapole, Jeruzaléma, Judska i Zajordání.',
    },
    5: {
        1: 'Když spatřil zástupy, vystoupil na horu. A když se posadil, přistoupili k němu jeho učedníci.',
        2: 'Otevřel ústa a učil je:',
        3: '„Blahoslavení chudí duchem, neboť jejich je království Nebes.',
        4: 'Blahoslavení plačící, neboť oni budou potěšeni.',
        5: 'Blahoslavení tiší, neboť oni dostanou zemi do dědictví.',
        6: 'Blahoslavení ti, kdo hladovějí a žízní po spravedlnosti, neboť oni budou nasyceni.',
        7: 'Blahoslavení milosrdní, neboť oni dojdou milosrdenství.',
        8: 'Blahoslavení čistého srdce, neboť oni uvidí Boha.',
        9: 'Blahoslavení ti, kdo působí pokoj, neboť oni budou nazváni Božími syny.',
        10: 'Blahoslavení ti, kdo jsou pronásledováni pro spravedlnost, neboť jejich je království Nebes.',
        11: 'Když vás budou tupit a pronásledovat a mluvit proti vám lživě všecko zlé kvůli mně, jste blahoslavení.',
        12: 'Radujte se a jásejte, neboť hojná je vaše odplata v nebesích; vždyť takto pronásledovali proroky, kteří byli před vámi.“',
        13: '„Vy jste sůl země. Jestliže sůl ztratí chuť, čím bude osolena? Nehodí se již k ničemu, než aby ji vyhodili a lidé po ní šlapali.',
        14: 'Vy jste světlo světa. Nemůže být ukryto město ležící na hoře.',
        15: 'A když rozsvítí lampu, nekladou ji pod nádobu, ale na stojan; a svítí všem, kteří jsou v domě.',
        16: 'Tak ať vaše světlo září před lidmi, aby uviděli vaše dobré skutky a vzdali slávu vašemu Otci, který je v nebesích.“',
        17: '„Nedomnívejte se, že jsem přišel zrušit Zákon nebo Proroky; nepřišel jsem je zrušit, nýbrž naplnit.',
        18: 'Neboť ⌈amen, pravím vám:⌉ Dokud nepomine nebe a země, nepomine jediné ⌈nejmenší písmenko⌉ ani jedna čárka ze Zákona, dokud se všechno nestane.',
        19: 'Kdo by tedy zrušil jediné z těchto nejmenších přikázání a tak učil lidi, bude v království Nebes nazván nejmenším. Kdo by je však ⌈činil a učil⌉, ten bude v království Nebes nazván velkým.',
        20: 'Neboť vám pravím: Nebude–li vaše spravedlnost o mnoho převyšovat spravedlnost učitelů Zákona a farizeů, do království Nebes určitě nevstoupíte.“',
        21: '„Slyšeli jste, že bylo řečeno předkům: Nezavraždíš. Kdo by zavraždil, propadne soudu.',
        22: 'Já vám však pravím, že soudu propadne každý, kdo se [bez příčiny] hněvá na svého bratra. Kdo by svému bratru řekl: Raka, propadne veleradě. Kdo by mu řekl: Blázne, propadne ohnivé Gehenně.',
        23: 'Jestliže tedy přinášíš svůj dar na oltář a tam si vzpomeneš, že tvůj bratr má něco proti tobě,',
        24: 'zanech tam před oltářem svůj dar a odejdi; nejprve se usmiř se svým bratrem, a pak přijď a obětuj svůj dar.',
        25: '⌈Dohodni se⌉ se svým odpůrcem rychle, dokud jsi s ním na cestě, aby tě snad odpůrce nevydal soudci a soudce strážci, a byl bys uvržen do vězení.',
        26: '⌈Amen, pravím⌉ tobě: Jistě odtamtud nevyjdeš, dokud nezaplatíš poslední haléř.“',
        27: '„Slyšeli jste, že bylo řečeno [předkům]: Nezcizoložíš.',
        28: 'Já však vám pravím, že každý, kdo hledí na ženu tak, ⌈že po ní zatouží⌉, již s ní zcizoložil ve svém srdci.',
        29: 'Jestliže tě tvé pravé oko svádí, vyjmi je a odhoď od sebe; neboť je pro tebe lépe, aby zahynul jeden z tvých údů, než aby celé tvé tělo bylo vrženo do Gehenny.',
        30: 'A jestliže tě svádí tvá pravá ruka, utni ji a odhoď od sebe; neboť je pro tebe lépe, aby zahynul jeden z tvých údů, než aby celé tvé tělo odešlo do Gehenny.“',
        31: '„Také bylo řečeno: Kdo propustí svou ženu, ať jí dá rozlukový list.',
        32: 'Ale já vám pravím, že každý, kdo propouští svou ženu, kromě případu smilstva, uvádí ji do cizoložství, a kdo by se s propuštěnou oženil, cizoloží.“',
        33: '„Dále jste slyšeli, že bylo řečeno předkům: ⌈Nebudeš křivě přísahat⌉, ale splníš Pánu své přísahy.',
        34: 'Já však vám pravím, abyste nepřísahali vůbec; ani při nebi, protože je to trůn Boží;',
        35: 'ani při zemi, protože je to podnož jeho nohou; ani při Jeruzalému, protože je to město velikého Krále.',
        36: 'Nepřísahej ani při své hlavě, protože ani jediný vlas nemůžeš učinit bílým nebo černým.',
        37: 'Ať je tedy vaše slovo ano, ano -- ne, ne; co je nad to, je ze Zlého.“',
        38: '„Slyšeli jste, že bylo řečeno: Oko za oko a zub za zub.',
        39: 'Já však vám pravím, abyste neodporovali zlému člověku, ale když tě někdo udeří do [tvé] pravé tváře, nastav mu i druhou tvář.',
        40: 'A tomu, kdo se s tebou chce soudit a vzít ti košili, nech i plášť.',
        41: 'A když tě někdo bude nutit k službě na jednu míli, jdi s ním dvě.',
        42: 'Tomu, kdo tě žádá, dej a od toho, kdo si od tebe chce vypůjčit, se neodvrať.“',
        43: '„Slyšeli jste, že bylo řečeno: Budeš milovat svého bližního a nenávidět svého nepřítele.',
        44: 'Já však vám pravím: Milujte své nepřátele, [žehnejte těm, kdo vás proklínají, dobře čiňte těm, kdo vás nenávidí,] a modlete se za ty, kteří vás [urážejí a] pronásledují,',
        45: 'abyste byli syny svého Otce, který je v nebesích; neboť on nechává své slunce vycházet nad zlými i dobrými a déšť posílá na spravedlivé i nespravedlivé.',
        46: 'Jestliže si zamilujete ty, kteří vás milují, jakou máte odměnu? Což i celníci nečiní totéž?',
        47: 'A pozdravíte–li jen své bratry, co činíte navíc? Nečiní totéž i pohané?',
        48: 'Buďte tedy dokonalí, jako je dokonalý váš nebeský Otec.“',
    },
    6: {
        1: '„Dávejte si pozor, abyste nekonali ⌈svou spravedlnost⌉ před lidmi, ⌈jim na odiv⌉; jinak nemáte odměnu u svého Otce, který je v nebesích.“',
        2: '„Když tedy ⌈dáváš almužnu⌉, nevytrubuj to před sebou, jak to činí pokrytci v synagogách a na ulicích, aby je lidé pochválili. Amen, pravím vám: Mají už svou odměnu.',
        3: 'Ale když ty ⌈dáváš almužnu⌉, ať tvá levice nepozná, co činí pravice,',
        4: 'aby tvá almužna zůstala skrytá. A tvůj Otec, který vidí v skrytu, ti odplatí [zjevně].“',
        5: '„A když se modlíte, nebuďte jako pokrytci; neboť ti se rádi modlí, stojíce v synagogách a na rozích ulic, aby je viděli lidé. Amen, pravím vám: Mají už svou odměnu.',
        6: 'Když ty se modlíš, vejdi do svého pokoje, zavři za sebou dveře a pomodli se k svému Otci, který je v skrytu, a tvůj Otec, který vidí v skrytu, ti odplatí [zjevně].',
        7: 'Když se modlíte, ⌈neopakujte naprázdno slova⌉ jako pohané, neboť ti se domnívají, že budou vyslyšeni pro množství svých slov.',
        8: 'Nebuďte proto jako oni; vždyť [Bůh,] váš Otec ví, co potřebujete, dříve, než jej poprosíte.',
        9: 'Vy se modlete takto: Otče náš, který jsi v nebesích, buď posvěceno tvé jméno.',
        10: 'Přijď tvé království. Staň se tvá vůle jako v nebi, tak i na zemi.',
        11: 'Náš denní chléb dej nám dnes.',
        12: 'A odpusť nám naše viny, jako jsme i my odpustili ⌈těm, kdo se provinili proti nám⌉.',
        13: 'A neuveď nás do pokušení, ale vysvoboď nás od ⌈toho Zlého⌉ [, neboť tvé je království i moc i sláva na věky. Amen].',
        14: 'Neboť jestliže odpustíte lidem jejich provinění, odpustí váš nebeský Otec i vám;',
        15: 'jestliže však lidem [jejich provinění] neodpustíte, ani váš Otec vám neodpustí vaše provinění.“',
        16: '„Když se postíte, nebývejte zasmušilí jako pokrytci; ⌈ ti se totiž tváří ztrápeně⌉, aby lidem ukázali, že se postí. Amen, pravím vám: Mají už svou odměnu.',
        17: 'Ale ty, když se postíš, potři svou hlavu olejem a svou tvář umyj,',
        18: 'abys neukázal lidem, že se postíš, ale svému Otci, který je v skrytu. A tvůj Otec, který vidí v skrytu, ti odplatí.“',
        19: '„Neshromažďujte si poklady na zemi, kde je ničí mol a rez a kde se zloději prokopávají a kradou.',
        20: 'Shromažďujte si poklady v nebi, kde je neničí mol ani rez a kde se zloději neprokopávají ani nekradou.',
        21: 'Neboť kde je tvůj poklad, tam bude i tvé srdce.“',
        22: '„Lampou těla je oko. Je–li tvé oko čisté, celé tvé tělo bude ⌈plné světla⌉.',
        23: 'Ale je–li tvé oko špatné, celé tvé tělo bude temné. Je–li tedy i světlo v tobě tmou, jak velká je pak temnota!“',
        24: '„Nikdo nemůže být otrokem dvou pánů; buď bude totiž jednoho nenávidět a druhého milovat, nebo se k jednomu upne a druhým pohrdne. Nemůžete sloužit Bohu i mamonu.“',
        25: '„Proto vám pravím: Nedělejte si starosti o svůj život, o to, co budete jíst [a co budete pít], ani o své tělo, o to, co si obléknete. Není život víc než pokrm a tělo víc než oděv?',
        26: 'Pohleďte na nebeské ptáky: nesejí, nežnou ani neshromažďují do stodol, a váš nebeský Otec je živí. Což vy nejste o mnoho cennější než oni?',
        27: 'Kdo z vás dokáže svou starostlivostí přidat ⌈k délce svého věku⌉ jediný loket?',
        28: 'A proč si děláte starosti o oděv? Podívejte se pozorně na polní lilie, jak rostou. Nenamáhají se ani nepředou,',
        29: 'a pravím vám, že ani Šalomoun v celé své slávě nebyl oblečen jako jedna z nich.',
        30: 'Jestliže tedy Bůh tak obléká polní trávu, která dnes je a kterou zítra hodí do pece, nebude tím spíše oblékat vás, malověrní?',
        31: 'Nepropadněte tedy starostem a neříkejte: Co budeme jíst? nebo: Co budeme pít? nebo: Co si oblečeme?',
        32: 'Neboť o to všechno horlivě usilují pohané. Vždyť váš nebeský Otec ví, že to všechno potřebujete.',
        33: 'Hledejte však nejprve Boží království a jeho spravedlnost, a to všechno vám bude přidáno.',
        34: 'Nedělejte si tedy starost kvůli zítřku, neboť zítřek ⌈bude mít své vlastní starosti⌉. Každý den má dost vlastního trápení.“',
    },
    7: {
        1: '„Nesuďte, abyste ⌈nebyli souzeni⌉.',
        2: 'Neboť jakým soudem soudíte, takovým budete souzeni, a jakou měrou měříte, takovou vám bude naměřeno.',
        3: 'Proč tedy hledíš na třísku v oku svého bratra, ale trámu ve svém oku si nevšímáš?',
        4: 'Anebo jak můžeš říkat svému bratru: Dovol, ať vyjmu třísku z tvého oka, a hle, ve tvém oku je trám?',
        5: 'Pokrytče, nejprve vyjmi trám ze svého oka, a pak jasně uvidíš, jak vyjmout třísku z oka svého bratra.',
        6: 'Nedávejte psům, co je svaté,a neházejte své perly před svině, aby je snad nohama nepošlapaly, neotočily se a neroztrhaly vás.“',
        7: '„Žádejte, a bude vám dáno; hledejte, a naleznete; tlučte, a bude vám otevřeno.',
        8: 'Neboť každý, kdo žádá, dostává, a kdo hledá, nalézá a tomu, kdo tluče, bude otevřeno.',
        9: 'Kdo z vás je takový člověk, který podá svému synu kámen, když ho požádá o chléb?',
        10: 'Nebo mu podá hada, když ho požádá o rybu?',
        11: 'Jestliže tedy vy, ač jste zlí, umíte svým dětem dávat dobré dary, čím spíše dá dobré věci těm, kteří ho žádají, váš Otec, který je v nebesích!',
        12: 'Všechno, co byste chtěli, aby lidé činili vám, čiňte i vy jim; neboť to je ⌈Zákon a Proroci.“⌉',
        13: '„Vejděte těsnou branou, protože široká je [brána] a prostorná cesta, která vede do záhuby; a mnoho je těch, kteří jí vcházejí.',
        14: 'Jak těsná je brána a zúžená cesta, která vede do života, a málo je těch, kdo ji nalézají!“',
        15: '„Mějte se na pozoru před falešnými proroky, kteří k vám přicházejí v rouchu ovčím, ale uvnitř jsou draví vlci.',
        16: 'Po jejich ovoci je poznáte. Což se sbírají z trní hrozny nebo z bodláčí fíky?',
        17: 'Tak každý dobrý strom nese dobré ovoce, ale prohnilý strom nese špatné ovoce.',
        18: 'Dobrý strom nemůže nést špatné ovoce ani prohnilý strom dobré ovoce.',
        19: 'Každý strom, který nenese dobré ovoce, bývá vyťat a hozen do ohně.',
        20: 'Poznáte je tedy po jejich ovoci.“',
        21: '„Ne každý, kdo mi říká: Pane, Pane, vejde do království Nebes, ale ten, kdo činí vůli mého Otce, který je v nebesích.',
        22: 'Mnozí mi v onen den řeknou: Pane, Pane, což jsme tvým jménem neprorokovali a tvým jménem nevyháněli démony a tvým jménem neučinili mnoho ⌈mocných činů⌉?',
        23: 'A tehdy jim vyznám: Nikdy jsem vás neznal. Odejděte ode mne, činitelé nepravosti. “',
        24: '„Každý, kdo slyší tato má slova a činí je, bude tedy podoben muži prozíravému, který postavil svůj dům na skále.',
        25: 'A spadl déšť a přihnaly se vody a zaduly větry a udeřily na ten dům -- ale nezřítil se, neboť byl založen na skále.',
        26: 'A každý, kdo slyší tato má slova a nečiní je, bude podoben muži pošetilému, který postavil svůj dům na písku.',
        27: 'A spadl déšť a přihnaly se vody a zaduly větry a udeřily na ten dům -- a zřítil se a jeho pád byl veliký.“',
        28: 'A stalo se, že když Ježíš dokončil tato slova, byly zástupy ohromeny jeho učením,',
        29: 'neboť je učil jako ten, kdo má pravomoc, a ne jako [jejich] učitelé Zákona.',
    },
    8: {
        1: 'Když sestoupil z hory, vydaly se za ním velké zástupy.',
        2: 'A hle, přišel malomocný, klaněl se mu a říkal: „Pane, chceš–li, jsi mocen mne očistit.“',
        3: 'On vztáhl ruku, dotkl se ho a řekl: „Chci, buď očištěn.“A hned byl očištěn od svého malomocenství.',
        4: 'Ježíš mu řekl: „Hleď, abys o tom nikomu neřekl. Ale jdi, ukaž se knězi a obětuj dar, který Mojžíš přikázal, jim na svědectví.“',
        5: 'Když vešel do Kafarnaum, přistoupil k němu jeden setník ⌈a prosil ho⌉:',
        6: '„Pane, můj sluha leží doma ochrnutý a hrozně trpí.“',
        7: '[Ježíš] mu řekl: „Já ⌈přijdu a uzdravím ho.⌉“',
        8: 'Setník však odpověděl: „Pane, nejsem hoden, abys vstoupil pod mou střechu; ale řekni jen slovo, a můj sluha bude uzdraven.',
        9: 'Vždyť i já jsem člověk ⌈ postavený pod pravomocí⌉ a mám pod sebou vojáky; a řeknu– li tomuto: Jdi, on jde; řeknu–li jinému: Přijď, přijde; a řeknu–li svému otroku: Udělej toto, pak to udělá.“',
        10: 'Když to Ježíš uslyšel, podivil se a řekl těm, kteří ho následovali: „Amen, pravím vám, takovou víru jsem v Izraeli nenašel u nikoho.',
        11: 'Pravím vám, že mnozí přijdou od východu i západu a budou stolovat s Abrahamem, Izákem a Jákobem v království Nebes;',
        12: 'avšak synové království ⌈budou vyvrženi⌉ do nejzazší temnoty; tam bude ⌈pláč a skřípění zubů.⌉“',
        13: 'I řekl Ježíš setníkovi: „Jdi, [a] staň se ti, jak jsi uvěřil.“A v tu hodinu byl [jeho] sluha uzdraven.',
        14: 'Když Ježíš přišel do Petrova domu, uviděl, že jeho tchyně leží a má horečku.',
        15: 'Dotkl se její ruky a horečka ji opustila; i vstala a obsluhovala ho.',
        16: 'Když nastal večer, přinesli k němu mnoho démonizovaných; i vyhnal duchy slovem a všechny nemocné uzdravil,',
        17: 'aby se naplnilo, co bylo řečeno skrze proroka Izaiáše: On sám naše slabosti vzal a nemoci nesl.',
        18: 'Když Ježíš kolem sebe uviděl zástup, rozkázal ⌈přeplavit se⌉ na druhou stranu.',
        19: 'Tu přišel jeden učitel Zákona a řekl mu: „Učiteli, budu tě následovat, kamkoli půjdeš.“',
        20: 'A Ježíš mu řekl: „Lišky mají doupata a nebeští ptáci hnízda, ale Syn člověka nemá, kde by hlavu složil.“',
        21: 'Jiný z [jeho] učedníků mu řekl: „Pane, dovol mi nejprve odejít a pohřbít svého otce.“',
        22: 'Ježíš mu však řekl: „Následuj mě a nech mrtvé, ať pohřbí své mrtvé.“',
        23: 'Pak vstoupil do lodi a jeho učedníci ho následovali.',
        24: 'A hle, na moři se strhla veliká bouře, takže vlny zakrývaly loď; on však spal.',
        25: 'I přišli [jeho učedníci], vzbudili ho a řekli: „Pane, zachraň [nás], hyneme!“',
        26: 'Řekl jim: „Proč jste ustrašení, vy malověrní?“Pak vstal, pohrozil větrům i moři; a nastal úplný klid.',
        27: 'Lidé užasli a říkali: „Kdo to asi je, že ho i větry a moře poslouchají?“',
        28: 'A když se dostal na druhou stranu do krajiny Gadarenských, setkali se s ním dva démonizovaní, kteří vyšli z hrobů. Byli velmi nebezpeční, takže tou cestou nemohl nikdo projít.',
        29: 'A hle, zakřičeli: „⌈Co je ti po nás⌉, [Ježíši,] Synu Boží? Přišel jsi sem, abys nás trýznil před ustanoveným časem?“',
        30: 'Daleko od nich se páslo stádo mnoha vepřů.',
        31: 'Démoni ho prosili: „Jestliže nás vyháníš, ⌈pošli nás⌉ do toho stáda vepřů!“',
        32: 'Řekl jim: „Jděte!“Oni vyšli a odešli do vepřů; a hle, celé stádo [vepřů] se zřítilo po svahu do moře a zahynulo ve vodách.',
        33: 'Pasáci utekli, a když přišli do města, vyprávěli všechno, i to o těch démonizovaných.',
        34: 'A hle, celé město vyšlo naproti Ježíšovi; a když ho spatřili, poprosili ho, aby odešel z jejich území.',
    },
    9: {
        1: 'Ježíš vstoupil na loď, přeplavil se a přišel do svého města.',
        2: 'A hle, přinášeli k němu ochrnutého, položeného na lůžku. Když Ježíš uviděl jejich víru, řekl ochrnutému: „⌈Buď dobré mysli⌉, synu, ⌈odpouštějí se⌉ ti [tvé] hříchy.“',
        3: 'A hle, někteří z učitelů Zákona si řekli: „Ten člověk se rouhá!“',
        4: 'Ježíš uviděl jejich myšlenky a řekl: „Proč smýšlíte ve svých srdcích zle?',
        5: 'Vždyť co je snadnější? Říci: ⌈Odpouštějí se ti⌉ hříchy, nebo říci: Vstaň a choď?',
        6: 'Abyste však věděli, že Syn člověka má pravomoc odpouštět na zemi hříchy …“Tu řekne ochrnutému: „Vstaň, vezmi své lůžko a jdi do svého domu.“',
        7: 'A on vstal a odešel do svého domu.',
        8: 'Když to uviděly zástupy, ⌈zmocnil se jich strach⌉ a vzdaly chválu Bohu, který dal lidem takovou pravomoc.',
        9: 'A když Ježíš odtamtud odcházel, uviděl v celnici sedět člověka jménem Matouš a řekl mu: „Následuj mne!“Matouš vstal a následoval ho.',
        10: 'A stalo se, když byl Ježíš u stolu v domě, hle, přišlo mnoho celníků a hříšníků, aby stolovali s ním a s jeho učedníky.',
        11: 'Když to uviděli farizeové, říkali jeho učedníkům: „Proč váš Učitel jí s celníky a hříšníky?“',
        12: 'Když to [Ježíš] uslyšel, řekl [jim]: „Lékaře nepotřebují zdraví, ale nemocní.',
        13: 'Jděte a naučte se, co znamená: Milosrdenství chci, a ne oběť. Neboť jsem nepřišel povolat spravedlivé, ale hříšníky [k pokání].“',
        14: 'Tehdy k němu přišli Janovi učedníci a řekli: „Proč se my a farizeové [často] postíme, ale tvoji učedníci se nepostí?“',
        15: 'Ježíš jim řekl: „Mohou svatebčané truchlit, dokud je s nimi ženich? Přijdou však dny, kdy jim bude ženich odebrán, a tehdy se budou postit.',
        16: 'Nikdo nedává záplatu z neseprané látky na starý šat; ta ková výplň se totiž ze šatu vytrhne a trhlina se ještě zhorší.',
        17: 'Ani se nedává mladé víno do starých měchů, jinak se ty měchy roztrhnou, víno vyteče a měchy se zničí. Mladé víno se dává do nových měchů, a obojí zůstane zachováno.“',
        18: 'Když jim to říkal, hle, přišel jeden z ⌈představených synagogy ⌉, klaněl se mu a řekl: „Má dcera právě zemřela; ale pojď, vlož na ni svou ruku, a bude žít.“',
        19: 'Ježíš vstal a šel za ním i se svými učedníky.',
        20: 'A hle, žena dvanáct let trpící krvotokem přišla zezadu a dotkla se třásní jeho šatu.',
        21: 'Neboť si říkala: „Jestliže se jen dotknu jeho šatu, budu zachráněna.“',
        22: 'Ježíš se otočil, a když ji spatřil, řekl: „Buď dobré mysli, dcero, tvá víra tě zachránila.“A od té hodiny byla ta žena zachráněna.',
        23: 'Když Ježíš vstoupil do domu představeného synagogy a uviděl pištce a hlučící zástup,',
        24: 'říkal: „Odejděte! Vždyť ta dívka nezemřela, ale spí.“I posmívali se mu.',
        25: 'A když byl zástup vyhnán, vešel, uchopil její ruku a děvče se probudilo.',
        26: 'A zpráva o tom se rozšířila do celé té země.',
        27: 'Když odtamtud Ježíš odcházel, vydali se za ním dva slepci, ⌈kteří křičeli⌉: „Smiluj se nad námi, synu Davidův!“',
        28: 'A když vešel do domu, přistoupili ti slepci k němu. Ježíš jim řekl: „Věříte, že ⌈to mohu⌉ učinit?“Řekli mu: „Ano, Pane.“',
        29: 'Nato se dotkl jejich očí a řekl: „Staň se vám podle vaší víry!“',
        30: 'A jejich oči se otevřely. Ježíš jim pohrozil a řekl: „Hleďte, ať o tom nikdo neví!“',
        31: 'Oni však vyšli a ⌈rozšířili zprávu o něm⌉ po celé té zemi.',
        32: 'Když odcházeli, hle, přivedli k němu němého démonizovaného [člověka].',
        33: 'A když byl démon vyhnán, němý promluvil. A zástupy užasly a říkaly: „ Něco takového se v Izraeli nikdy nestalo.“',
        34: 'Ale farizeové říkali: „⌈V moci ⌉ vládce démonů vyhání démony.“',
        35: 'Ježíš obcházel všechna města i vesnice, učil v jejich synagogách, hlásal evangelium království a uzdravoval každou nemoc a každou slabost [v lidu].',
        36: 'Když uviděl zástupy, byl nad nimi hluboce pohnut, protože byli utrápení a sklíčení jako ovce, které nemají pastýře.',
        37: 'Tehdy řekl svým učedníkům: „Žeň je velká, dělníků je však málo.',
        38: 'Proste tedy Pána žně, aby poslal dělníky na svou žeň.“',
    },
    10: {
        1: 'Zavolal si svých dvanáct učedníků a dal jim pravomoc nad nečistými duchy, aby je vyháněli a aby uzdravovali každou nemoc i každou slabost.',
        2: 'Jména těch dvanácti apoštolů jsou tato: první Šimon zvaný Petr, jeho bratr Ondřej, Jakub Zebedeův a jeho bratr Jan,',
        3: 'Filip, Bartoloměj, Tomáš, celník Matouš, Jakub Alfeův, Tadeáš,',
        4: 'Šimon Kananejský a Juda Iškariotský, který ho pak zradil.',
        5: 'Těchto dvanáct Ježíš poslal, když jim předtím nařídil: „Nechoďte na cestu pohanů a do samařského města nevstupujte;',
        6: 'ale jděte raději k zahynulým ovcím z domu Izraele.',
        7: 'Cestou hlásejte: Přiblížilo se království Nebes.',
        8: 'Uzdravujte nemocné, probouzejte mrtvé, očišťujte malomocné, vyhánějte démony -- zadarmo jste přijali, zadarmo dejte.',
        9: 'Neopatřujte si do svých opasků zlato ani stříbro ani měď;',
        10: 'neberte si na cestu ani mošnu ani dvě košile ani sandály ani hůl, neboť dělník je hoden své obživy.',
        11: 'Do kteréhokoli města nebo vesnice vejdete, vyptejte se, kdo v něm je toho hoden; a tam zůstaňte, dokud neodejdete.',
        12: 'Když budete vcházet do domu, pozdravte jej.',
        13: 'Bude–li toho ten dům vskutku hoden, ať na něj přijde váš pokoj. Nebude–li však toho hoden, ať se váš pokoj navrátí k vám.',
        14: 'A když vás někdo nepřijme a nevyslechne vaše slova, při odchodu z toho domu nebo onoho města vytřeste prach se svých nohou.',
        15: 'Amen, pravím vám, v den soudu bude snesitelněji sodomské a gomorské zemi než onomu městu.“',
        16: '„Hle, já vás posílám jako ovce mezi vlky; buďte tedy obezřetní jako hadi a prostí jako holubice.',
        17: 'Mějte se na pozoru před lidmi, neboť vás budou vydávat soudům, budou vás bičovat ve svých synagogách,',
        18: 'dokonce před vladaře a krále vás budou vodit kvůli mně, jim i pohanům na svědectví.',
        19: 'A když vás vydají, nestarejte se, jak nebo co promluvit; neboť v tu hodinu vám bude dáno, co máte promluvit.',
        20: 'Vždyť to nejste vy, kdo mluví, ale ⌈Duch vašeho Otce⌉, jenž mluví ve vás.',
        21: 'Vydá na smrt bratr bratra a otec dítě, povstanou děti proti rodičům a usmrtí je.',
        22: 'A všichni vás budou nenávidět pro mé jméno. Kdo však vytrvá do konce, bude zachráněn.',
        23: 'Když vás budou pronásledovat v jednom městě, utečte do jiného; neboť amen, pravím vám, jistě nebudete hotovi s izraelskými městy, než přijde Syn člověka.“',
        24: '„Učedník není nad učitele ani otrok nad svého pána.',
        25: 'Stačí, aby učedník byl jako jeho učitel a otrok jako jeho pán. Jestliže hospodáře nazvali Belzebulem, tím spíše jeho čeleď!“',
        26: '„Nebojte se jich tedy; neboť není nic zahaleného, co nebude zjeveno, a nic skrytého, co nebude poznáno.',
        27: 'Co vám pravím ve tmě, řekněte na světle; a co slyšíte šeptem do ucha, vyhlaste ze střech.',
        28: 'A nebojte se těch, kdo zabíjejí tělo, ale duši zabít nemohou. Raději se bojte toho, kdo může i duši i tělo zahubit v Gehenně.',
        29: 'Neprodávají se dva vrabci za haléř? A ani jeden z nich nespadne na zem bez vůle vašeho Otce.',
        30: 'I všechny vlasy na vaší hlavě jsou spočteny.',
        31: 'Nebojte se tedy; vy jste cennější než mnoho vrabců.“',
        32: '„Ke každému, kdo se ke mně přizná před lidmi, se i já přiznám před svým Otcem, který je v nebesích.',
        33: 'Kdo mě však před lidmi zapře, toho i já zapřu před svým Otcem, který je v nebesích.“',
        34: '„Nemyslete si, že jsem přišel uvést na zem pokoj; nepřišel jsem uvést pokoj, ale meč.',
        35: 'Neboť jsem přišel postavit člověka proti jeho otci, dceru proti její matce a snachu proti její tchyni',
        36: 'a nepřáteli člověka budou členové jeho domácnosti.',
        37: 'Kdo má rád otce nebo matku víc než mne, není mne hoden; a kdo má rád syna nebo dceru víc než mne, není mne hoden.',
        38: 'A kdo jde za mnou a nebere svůj kříž, není mne hoden.',
        39: 'Kdo nalezne ⌈svou duši⌉, ztratí ji; a kdo ztratí ⌈svou duši⌉ kvůli mně, nalezne ji.“',
        40: '„Kdo přijímá vás, přijímá mne; a kdo přijímá mne, přijímá toho, který mne poslal.',
        41: 'Kdo přijímá proroka ⌈proto, že je to prorok⌉, obdrží odměnu proroka; a kdo přijímá spravedlivého ⌈proto, že je to spravedlivý,⌉ obdrží odměnu spravedlivého.',
        42: 'A kdo by jednomu z těchto maličkých dal napít ⌈proto, že je učedník⌉, i kdyby mu dal jen pohár studené [vody], amen, pravím vám, jistě nepřijde o svou odměnu.“',
    },
    11: {
        1: 'A stalo se, když Ježíš dokončil příkazy svým dvanácti učedníkům, že odtamtud odešel, aby učil a kázal v jejich městech.',
        2: 'Jan uslyšel ve vězení o Kristových činech, poslal ⌈ vzkaz po svých učednících⌉',
        3: '⌈a otázal se ho:⌉ „Ty jsi ⌈Ten, který má přijít⌉, nebo máme očekávat jiného?“',
        4: 'Ježíš jim odpověděl: „Jděte a oznamte Janovi, co slyšíte a vidíte:',
        5: 'Slepí opět vidí, chromí chodí, malomocní jsou očišťováni, hluší slyší, mrtví vstávají a chudým se zvěstuje evangelium.',
        6: 'Blahoslavený je ten, kdo by se nade mnou nepohoršil.“',
        7: 'Zatímco odcházeli, začal Ježíš říkat zástupům o Janovi: „Co jste vyšli spatřit do pustiny? Třtinu zmítanou větrem?',
        8: 'Nebo co jste vyšli uvidět? Člověka oblečeného do jemných [šatů]? Hle, ti, kdo nosí jemné šaty, jsou v ⌈královských palácích⌉.',
        9: 'Ale co jste vyšli uvidět? Proroka? Ano, pravím vám, a více než proroka.',
        10: 'To je ten, o němž je napsáno: Hle, já posílám svého posla před tvou tváří, který upraví tvou cestu před tebou.',
        11: 'Amen, pravím vám, mezi těmi, kdo se narodili z ženy, nepovstal nikdo větší než Jan Křtitel; avšak ten nejmenší v království Nebes je větší než on.',
        12: 'Ode dnů Jana Křtitele až dosud ⌈je království Nebes vystaveno tlaku a ti, kdo se do něho tlačí,⌉ je uchvacují.',
        13: 'Neboť všichni Proroci i Zákon prorokovali až do Jana.',
        14: 'A chcete–li to přijmout, on je Eliáš, který má přijít.',
        15: 'Kdo má uši [k slyšení], ať naslouchá.“',
        16: '„Ke komu připodobním toto pokolení? Je podobné dětem, které sedí na tržištích a volají na ostatní:',
        17: 'Pískali jsme vám, a vy jste netancovali; naříkali jsme, a vy ⌈jste se nebili v prsa⌉.',
        18: 'Přišel Jan, nejedl a nepil, a říkají: Má démona!',
        19: 'Přišel Syn člověka, jí a pije, a říkají: Hle, člověk žrout a pijan vína, přítel celníků a hříšníků! Ale moudrost je ospravedlněna svými dětmi.“',
        20: 'Tehdy začal Ježíš kárat města, ve kterých se stalo nejvíc jeho mocných činů, že nečinila pokání.',
        21: '„Běda tobě, Chorazin! Běda tobě, Betsaido! Protože kdyby se byly v Týru a Sidónu staly ty mocné činy, které se staly ve vás, dávno by v žíni a popelu učinili pokání.',
        22: 'Ale pravím vám: Týru a Sidónu bude v den soudu snesitelněji než vám.',
        23: 'A ty, Kafarnaum, ⌈budeš snad vyvýšeno⌉ až do nebe? Až do podsvětí budeš strženo! Neboť kdyby se v Sodomě staly mocné činy, které se staly v tobě, zůstala by až do dnešního dne.',
        24: 'Ale pravím vám, že sodomské zemi bude v den soudu snesitelněji nežli tobě.“',
        25: 'V ten čas pak Ježíš řekl: „Vzdávám ti chválu, Otče, Pane nebe i země, že jsi skryl tyto věci před moudrými a rozumnými a zjevil jsi je maličkým.',
        26: 'Ano, Otče, protože tak ⌈se ti zalíbilo.⌉',
        27: 'Všechno mi předal můj Otec; a nikdo nezná Syna, jen Otec, ani Otce nikdo nezná, jen Syn a ten, komu by ho Syn chtěl zjevit.',
        28: 'Pojďte ke mně všichni, kteří těžce pracujete a jste přetíženi, a já vám dám odpočinek.',
        29: 'Vezměte na sebe mé jho a učte se ode mne, neboť jsem tichý a pokorný v srdci; a naleznete odpočinutí svým duším.',
        30: 'Vždyť mé jho je příjemné a mé břemeno je lehké.“',
    },
    12: {
        1: 'V ten čas šel Ježíš v sobotu obilím. Jeho učedníci dostali hlad a začali trhat klasy a jíst.',
        2: 'Když [je] uviděli farizeové, řekli mu: „Hle, tvoji učedníci dělají, co se v sobotu dělat nesmí.“',
        3: 'On jim však řekl: „Nečetli jste, co udělal David, když vyhladověl, on i ti, kdo byli s ním?',
        4: 'Jak vešel do Božího domu a jak snědli ⌈chleby předložení⌉, které nesměl jíst ani on ani ti, kdo byli s ním, ale jen kněží?',
        5: 'Anebo nečetli jste v Zákoně, že o sobotách kněží v chrámě porušují sobotu, a přece jsou bez viny?',
        6: 'Pravím vám, že zde je někdo větší než chrám.',
        7: 'Kdybyste věděli, co znamená: Milosrdenství chci, a ne oběť, neodsoudili byste nevinné.',
        8: 'Vždyť Syn člověka je pánem soboty.“',
        9: 'A když odtamtud odešel, přišel do jejich synagogy.',
        10: 'A hle, byl tam člověk, který měl odumřelou ruku. I otázali se ho: „Je dovoleno v sobotu uzdravovat?“To proto, aby jej obžalovali.',
        11: 'On jim řekl: „⌈Kdyby měl někdo z vás ovci⌉ a ta by mu v sobotu spadla do jámy, což by ji neuchopil a nevytáhl?',
        12: 'Oč je člověk cennější než ovce! Proto je dovoleno v sobotu činit dobře.“',
        13: 'Potom tomu člověku řekl: „Natáhni svou ruku.“Natáhl ji, a byla zase v pořádku a zdravá jako ta druhá.',
        14: 'Farizeové však vyšli a radili se proti němu, jak by ho zahubili.',
        15: 'Ježíš to věděl a odešel odtamtud. A následovaly jej ⌈velké zástupy⌉ a on je všechny uzdravil;',
        16: 'a přísně jim domluvil, aby ⌈nerozšiřovali pověst o něm⌉.',
        17: 'To proto, aby se naplnilo, co bylo řečeno skrze proroka Izaiáše:',
        18: 'Hle, můj služebník, kterého jsem si vyvolil, můj milovaný, kterého si oblíbila má duše. Vložím na něho svého Ducha a ohlásí soud národům.',
        19: 'Nebude se přít ani křičet, na ulicích nikdo neuslyší jeho hlas.',
        20: 'Nalomený rákos nedolomí a doutnající knot neuhasí, dokud nepřivede právo k vítězství.',
        21: 'A v jeho jméno budou národy skládat naději.',
        22: 'Tehdy k němu přivedli démonizovaného, který byl slepý a němý. Uzdravil ho, takže ten němý [a slepý] mluvil a viděl.',
        23: 'A všechny zástupy byly ohromeny a říkaly: „Snad to není ten Syn Davidův?“',
        24: 'Když to uslyšeli farizeové, řekli: „Ten člověk vyhání démony jen ⌈v moci ⌉ Belzebula, vládce démonů.“',
        25: '[Ježíš] však znal jejich myšlenky a řekl jim: „Každé království samo proti sobě rozdělené pustne a žádné město nebo dům sám proti sobě rozdělený neobstojí.',
        26: 'A vyhání–li Satan Satana, rozdělil se sám proti sobě. Jak tedy obstojí jeho království?',
        27: 'A vyháním–li já démony ⌈v moci ⌉ Belzebula, v čí moci je vyhánějí vaši synové? Proto oni budou vašimi soudci.',
        28: 'Jestliže však já vyháním démony ⌈v moci ⌉ Ducha Božího, pak už k vám přišlo Boží království.',
        29: 'Nebo jak může někdo vejít do domu siláka a uloupit jeho majetek, jestliže siláka nejdříve nespoutá? A teprve pak vyloupí jeho dům.',
        30: 'Kdo není se mnou, je proti mně, a kdo neshromažďuje se mnou, rozptyluje.',
        31: 'Proto vám pravím: Každý hřích i rouhání bude lidem odpuštěno, ale rouhání proti Duchu odpuštěno nebude.',
        32: 'A tomu, kdo by řekl slovo proti Synu člověka, bude odpuštěno; ale tomu, kdo by promluvil proti Duchu Svatému, nebude odpuštěno ani v tomto věku, ani v budoucím.“',
        33: '„Vypěstujte krásný strom, a jeho ovoce bude krásné, nebo vypěstujte špatný strom, a jeho ovoce bude špatné. Vždyť strom se pozná podle ovoce.',
        34: 'Plemeno zmijí, jak můžete mluvit dobré věci, když jste zlí? Vždyť ústa mluví z přebytku srdce.',
        35: 'Dobrý člověk z dobrého pokladu vynáší dobré, a zlý člověk ze zlého pokladu vynáší zlé.',
        36: 'Pravím vám, že z každého neužitečného výroku, který lidé promluví, vydají počet v den soudu.',
        37: 'Neboť podle svých slov budeš ospravedlněn a podle svých slov odsouzen.“',
        38: 'Tehdy mu někteří z učitelů Zákona a farizeů řekli: „Učiteli, chceme od tebe uvidět znamení.“',
        39: 'On jim však odpověděl: „Pokolení zlé a cizoložné vyhledává znamení, ale znamení mu nebude dáno, kromě znamení proroka Jonáše.',
        40: 'Vždyť jako byl Jonáš v břiše velké ryby tři dny a tři noci, tak bude Syn člověka tři dny a tři noci v srdci země.',
        41: 'Ninivští muži povstanou na soudu s tímto pokolením a odsoudí je, neboť učinili pokání na Jonášovo kázání-- a hle, zde je někdo většínež Jonáš.',
        42: 'Královna jihu po vstane na soudu s tímto pokolením a odsoudí je, protože přišla od končin země, aby uslyšela Šalomounovu moudrost -- a hle, zde je někdo větší než Šalomoun.“',
        43: '„Když pak nečistý duch vyjde od člověka, prochází bezvodými místy, hledaje odpočinutí, ale nenalézá.',
        44: 'Tehdy si říká: Vrátím se do svého domu, odkud jsem vyšel. A když přijde, nalézá dům prázdný, zametený a vyzdobený.',
        45: 'Potom jde a vezme s sebou sedm jiných duchů, horších, než je sám; vejdou a bydlí tam. A poslední věci onoho člověka se stávají horšími než ty první. Tak bude i s tímto zlým pokolením.“',
        46: 'Když ještě mluvil k zástupům, hle, venku stáli jeho matka a bratři a chtěli s ním mluvit.',
        47: '[Kdosi mu řekl: „Hle, tvá matka a tvoji bratři stojí venku a chtějí s tebou mluvit.“]',
        48: 'On však tomu, kdo mu to říkal, odpověděl: „Kdo je má matka a kdo jsou moji bratři?“',
        49: '⌈Ukázal rukou⌉ na své učedníky a řekl: „Hle, má matka a moji bratři.',
        50: 'Neboť každý, kdo činí vůli mého Otce v nebesích, to je můj bratr, má sestra i matka.“',
    },
    13: {
        1: 'Toho dne vyšel Ježíš z domu a sedl si u moře.',
        2: 'I shromáždily se k němu velké zástupy. Proto vstoupil na loď a posadil se. Celý ten zástup stál na břehu.',
        3: 'A pověděl jim mnoho v podobenstvích: „Hle, vyšel rozsévač, ⌈aby rozséval⌉.',
        4: 'A jak rozséval, padla některá zrna podél cesty; i přiletěli ptáci a sezobali je.',
        5: 'Jiná padla na skalnatá místa, kde neměla mnoho země, a hned vzešla, protože neměla hlubokou zem.',
        6: 'Když vyšlo slunce, spálilo je; a protože neměla kořen, uschla.',
        7: 'Jiná padla do trní; a trní vzešlo a udusilo je.',
        8: 'Jiná padla do dobré země a vydávala úrodu, některá sto násobnou, jiná šedesát inásobnou, jiná třicet inásobnou.',
        9: 'Kdo má uši [k slyšení], ať poslouchá!“',
        10: 'Tu přistoupili učedníci a řekli mu: „Proč k nim mluvíš v podobenstvích?“',
        11: 'On jim odpověděl: „Vám je dáno poznat tajemství království Nebes, ale jim to dáno není.',
        12: 'Neboť kdo má, tomu bude dáno a bude mít nadbytek; avšak tomu, kdo nemá, bude odňato i to, co má.',
        13: 'Proto k nim mluvím v podobenstvích, protože hledíce nevidí a naslouchajíce neslyší ani nechápou.',
        14: 'Naplňuje se na nich Izaiášovo proroctví, které říká: Vskutku budete slyšet, a jistě nepochopíte, budete ustavičně hledět, a určitě neuvidíte.',
        15: 'Neboť srdce tohoto lidu ztučnělo, ušima začali slyšet ztěžka a své oči zavřeli, aby očima neuviděli a ušima neuslyšeli, srdcem nepochopili a neobrátili se, a já je neuzdravil.',
        16: 'Blahoslavené jsou vaše oči, že vidí, a vaše uši, že slyší.',
        17: 'Amen, pravím vám, že mnozí proroci a spravedliví toužili spatřit, co vidíte vy, ale nespatřili, a slyšet, co vy slyšíte, ale neslyšeli.',
        18: 'Vy tedy poslyšte ⌈podobenství o rozsévači⌉.',
        19: 'Ke každému, kdo slyší slovo o království a nerozumí, přichází ten Zlý a uchvacuje to, co bylo zaseto v jeho srdci; to je ten, který byl zaset podél cesty.',
        20: 'Zasetý na skalnatá místa, to je ten, kdo Slovo slyší a hned je s radostí přijímá,',
        21: 'nemá však v sobě kořen, ale je nestálý. Když pak nastane soužení nebo pronásledování pro Slovo, ihned odpadá.',
        22: 'Zasetý do trní, to je ten, kdo Slovo slyší, ale starost [tohoto] věku a svod bohatství Slovo dusí, a tak se stává neplodným.',
        23: 'Zasetý na dobrou půdu, to je ten, kdo Slovo slyší a rozumí mu; ten pak nese úrodu, jeden sto násobnou, druhý šedesát inásobnou, jiný třicet inásobnou.“',
        24: 'Předložil jim jiné podobenství: „Království Nebes ⌈je podobné⌉ člověku, který na svém poli zasel dobré semeno.',
        25: 'Zatímco lidé spali, přišel jeho nepřítel, rozesel mezi pšenici plevel a odešel.',
        26: 'Když pak osení vyrostlo a ⌈nasadilo na klas⌉, ukázal se i plevel.',
        27: 'Přišli otroci toho hospodáře a řekli mu: Pane, cožpak jsi nezasel na svém poli dobré semeno? Odkud ⌈se tedy vzal⌉ plevel?',
        28: 'On jim odpověděl: Nepřítel člověk to udělal. A otroci mu řekli: Chceš tedy, abychom šli a posbírali jej?',
        29: 'On však řekl: Ne, abyste snad při sbírání plevele nevytrhli z kořenů spolu s ním i pšenici.',
        30: 'Nechte, ať obojí roste spolu až do žně; a v čas žně řeknu žencům: Nejprve posbírejte plevel a svažte ho do otýpek, abyste jej zcela spálili, ale pšenici shromážděte do mé stodoly. “',
        31: 'Předložil jim jiné podobenství: „Království Nebes je podobné zrnu hořčice, které člověk vzal a zasel na svém poli.',
        32: 'Je sice menší než všecka semena, ale když vyroste, je větší než ostatní zahradní byliny a ⌈je z něho⌉ strom, takže přilétají nebeští ptáci a hnízdí v jeho větvích.“',
        33: 'Pověděl jim jiné podobenství: „Království Nebes je podobné kvasu, který žena vzala a skryla do tří měřic mouky, dokud to všecko nezkvasilo.“',
        34: 'To všechno mluvil Ježíš k zástupům v podobenstvích a bez podobenství k nim [vůbec] nemluvil,',
        35: 'aby se naplnilo,co bylo řečeno skrze proroka [Izaiáše]: Otevřu svá ústa v podobenstvích, vypovím, co bylo skryté od založení [světa].',
        36: 'Potom opustil [Ježíš] zástupy a vešel do domu. I přistoupili k němu jeho učedníci a řekli: „Vylož nám to podobenství o plevelu na poli.“',
        37: 'On [jim] odpověděl: „Rozsévač dobrého semena je Syn člověka',
        38: 'a pole je svět. Dobré semeno, to jsou synové království, plevel jsou synové toho Zlého;',
        39: 'nepřítel, který je zasel, je Ďábel. Žeň je skonání věku a ženci jsou andělé.',
        40: 'Jako se tedy sbírá plevel a ⌈pálí se v ohni⌉, tak bude při skonání [tohoto] věku.',
        41: 'Syn člověka pošle své anděly, i seberou z jeho království všechna pohoršení a ty, kdo činí nepravost,',
        42: 'a hodí je do ohnivé pece; tam bude pláč a skřípění zubů.',
        43: 'Tehdy se spravedliví rozzáří jako slunce v království svého Otce. Kdo má uši [k slyšení], ať poslouchá!“',
        44: '„Království Nebes je podobné pokladu skrytému v poli, který člověk nalezl a skryl; a z radosti nad ním jde a prodává všechno, co má, a kupuje ono pole.',
        45: 'Království Nebes je dále podobné člověku kupci, hledajícímu krásné perly.',
        46: 'Když našel jednu drahocennou perlu, odešel a prodal vše, co měl, a koupil ji.',
        47: 'Dále je království Nebes podobné síti, která byla spuštěna do moře a shromáždila všechny druhy ryb.',
        48: 'Když se naplnila, vytáhli ji na břeh, posadili se, dobré sebrali do nádob a špatné vyhodili ven.',
        49: 'Tak tomu bude při skonání věku: Vyjdou andělé, oddělí zlé zprostředka spravedlivých',
        50: 'a hodí je do ohnivé pece; tam bude pláč a skřípění zubů.“',
        51: '[Ježíš jim řekl:] „Rozuměli jste tomu všemu?“Řekli mu: „Ano, [Pane].“',
        52: 'On jim řekl: „Proto se každý učitel Zákona, ⌈který se stal učedníkem⌉ království Nebes, podobá člověku hospodáři, který ze svého pokladu vynáší nové i staré.“',
        53: 'Když Ježíš dokončil tato podobenství, odešel odtamtud.',
        54: 'Přišel do svého domovského města a učil je v jejich synagoze, takže ohromeni říkali: „Odkud se u něj vzala taková moudrost a mocné činy?',
        55: 'Není to ten syn tesařův? Nejmenuje se jeho matka Marie a jeho bratři Jakub, Josef, Šimon a Juda?',
        56: 'A nejsou všechny jeho sestry u nás? Odkud tedy má toto všechno?“',
        57: 'A pohoršovali se nad ním. Ale Ježíš jim řekl: „Prorok není beze cti, leda ve [své] vlasti a ve svém domě.“',
        58: 'A pro jejich nevěru tam neučinil mnoho mocných činů.',
    },
    14: {
        1: 'V ten čas uslyšel tetrarcha Herodes pověst o Ježíšovi',
        2: 'a řekl svým sluhům: „To je Jan Křtitel. Vstal z mrtvých, a proto v něm působí ty to moci.“',
        3: 'Herodes se totiž zmocnil Jana, spoutal [ho] a uvrhl do vězení kvůli Herodiadě, ženě svého bratra Filipa,',
        4: 'neboť Jan mu říkal: „Není ti dovoleno ji mít.“',
        5: 'Herodes ho chtěl zabít, ale bál se lidu, protože ho pokládali za proroka.',
        6: '⌈Když však nastal den Herodových narozenin⌉, zatančila dcera té Herodiady mezi hosty, a zalíbila se Herodovi,',
        7: 'takže jí s přísahou slíbil dát, o cokoli požádá.',
        8: 'Ona pak, navedena svou matkou, řekla: „Dej mi zde na míse hlavu Jana Křtitele.“',
        9: 'Král se zarmoutil, ale kvůli těm přísahám a spolustolovníkům poručil, aby [jí] byla dána;',
        10: 'dal tedy Jana ve vězení stít.',
        11: 'Jeho hlavu přinesli na míse a dali ji té dívce a ta ji donesla své matce.',
        12: 'I přišli jeho učedníci, vzali tělo a pohřbili je; pak šli a oznámili to Ježíšovi.',
        13: 'Jakmile to Ježíš uslyšel, odplul odtamtud v lodi do ústraní na opuštěné místo; ale zástupy o tom uslyšely a vydaly se z měst pěšky za ním.',
        14: 'Když vystoupil, uviděl veliký zástup, byl nad nimi hluboce pohnut a uzdravil jejich nemocné.',
        15: 'A když nastal večer, přistoupili k němu učedníci a řekli: „Toto místo je opuštěné a hodina již pokročila; propusť zástupy, ať odejdou do vesnic a nakoupí si jídlo.“',
        16: '[Ježíš] jim řekl: „Nemusejí odejít; vy jim dejte najíst!“',
        17: 'Oni mu řekli: „Nemáme zde než pět chlebů a dvě ryby.“',
        18: 'On však řekl: „Přineste mi je sem!“',
        19: 'A poručil zástupům, aby se rozložily na trávě, vzal těch pět chlebů a dvě ryby, vzhlédl k nebi, požehnal, rozlámal chleby a dal je učedníkům a učedníci zástupům.',
        20: 'Všichni jedli a nasytili se. A sebrali dvanáct plných nůší zbylých úlomků.',
        21: 'Těch, kdo jedli, bylo asi pět tisíc mužů, kromě žen a dětí.',
        22: 'A Ježíš hned přinutil [své] učedníky, aby nastoupili do lodi a jeli před ním na druhou stranu, než on propustí zástupy.',
        23: 'A když zástupy propustil, vystoupil na horu, aby se o samotě pomodlil. Když nastal večer, byl tam sám.',
        24: 'Loď již byla ⌈od země vzdálena mnoho stadií⌉, zmítána vlnami, protože vítr vál proti ní.',
        25: 'O čtvrté noční hlídce šel [Ježíš] k nim, kráčeje po moři.',
        26: 'Když ho učedníci uviděli kráčet po moři, vyděsili se a řekli: „ To je přízrak!“A strachem vykřikli.',
        27: '[Ježíš] na ně hned promluvil: „Vzchopte se, já jsem to, nebojte se!“',
        28: 'Petr mu odpověděl: „Pane, jsi–li to ty, poruč mi, ať přijdu k tobě po vodě!“',
        29: 'On řekl: „Pojď!“Petr vystoupil z lodi, kráčel po vodě a přišel k Ježíšovi.',
        30: 'Ale když viděl [silný] vítr, dostal strach. ⌈Začal tonout⌉ a vykřikl: „Pane, zachraň mě!“',
        31: 'Ježíš hned vztáhl ruku, zachytil ho a řekl mu: „Malověrný, proč jsi zapochyboval?“',
        32: 'A když vstoupili na loď, vítr přestal.',
        33: 'Ti, kdo byli v lodi, se mu poklonili a řekli: „Opravdu jsi Boží Syn.“',
        34: 'Přeplavili se a dorazili k zemi u Genezaretu.',
        35: 'Jakmile ho muži z toho místa poznali, poslali zprávu do celého okolí. Přinesli k němu všechny nemocné',
        36: 'a prosili ho, aby se směli jen dotknout třásní jeho šatu; a všichni, kdo se dotkli, byli uzdraveni.',
    },
    15: {
        1: 'Tehdy přišli k Ježíšovi z Jeruzaléma farizeové a učitelé Zákona a řekli:',
        2: '„Proč tvoji učedníci přestupují tradici starších? Vždyť si neomývají [své] ruce, když jedí chléb.“',
        3: 'On jim odpověděl: „Proč i vy přestupujete Boží příkaz kvůli své tradici?',
        4: 'Vždyť Bůh řekl: Cti otce a matku a kdo zlořečí otci nebo matce, ať zemře.',
        5: 'Vy však říkáte: Kdo by řekl otci nebo matce: To z mého majetku, co by ti mohlo pomoci, je dar určený Bohu,',
        6: 'ten již není povinen uctít svého otce [nebo svou matku]. Zrušili jste Boží slovo pro svou tradici.',
        7: 'Pokrytci! Dobře o vás prorokoval Izaiáš, když říkal:',
        8: '⌈Tento lid mne ctí rty⌉, ale jejich srdce je ode mne velmi daleko.',
        9: 'Marně mne však uctívají, vyučujíce nauky, jež jsou jen lidskými příkazy. “',
        10: 'Zavolal k sobě zástup a řekl: „Slyšte a rozumějte.',
        11: 'Člověka neznečišťuje to, co vchází do úst, nýbrž člověka znečišťuje to, co z úst vychází.“',
        12: 'Tu k němu přistoupili [jeho] učedníci a řekli mu: „Víš, že se farizeové pohoršili, když to slovo uslyšeli?“',
        13: 'On odpověděl: „Každá rostlina, kterou nezasadil můj nebeský Otec, bude vykořeněna.',
        14: 'Nechte je! Slepí jsou vůdci [slepých]. Jestliže slepý vede slepého, oba spadnou do jámy.“',
        15: 'Petr mu ⌈na to⌉ řekl: „Vylož nám [toto] podobenství!“',
        16: '[Ježíš] řekl: „I vy jste ještě nechápaví?',
        17: 'Nerozumíte, že všechno, co vchází do úst, jde do břicha a vypouští se do záchodu?',
        18: 'Co však z úst vychází, vystupuje ze srdce, a to znečišťuje člověka.',
        19: 'Neboť ze srdce vycházejí špatné myšlenky, vraždy, cizoložství, smilstva, krádeže, lživá svědectví, urážky.',
        20: 'To jsou věci, které člověka znečišťují; ale jíst neomytýma rukama člověka neznečišťuje.“',
        21: 'Ježíš odtamtud vyšel a odebral se do končin Týru a Sidónu.',
        22: 'A hle, z těch končin vyšla nějaká kananejská žena a křičela: „Smiluj se nade mnou, Pane, Synu Davidův! Mou dceru zle ⌈trápí démon⌉.“',
        23: 'Ale on jí neodpověděl ani slovo. I přistoupili k němu jeho učedníci a prosili ho: „⌈Pošli ji pryč⌉, vždyť za námi křičí!“',
        24: 'On řekl: „⌈Byl jsem poslán jen⌉ ke ztraceným ovcím z domu Izraele.“',
        25: 'Ona však přišla, ⌈klaněla se mu⌉ a říkala: „Pane, pomoz mi!“',
        26: 'On odpověděl: „Není správné vzít chléb dětem a hodit jej psům.“',
        27: 'Ona řekla: „Ano, Pane, ale vždyť i psi jedí z drobtů, které padají se stolu jejich pánů.“',
        28: 'Tehdy jí Ježíš odpověděl: „Ó ženo, tvá víra je veliká. Staň se ti, jak chceš.“A od té hodiny byla její dcera uzdravena.',
        29: 'A přecházeje odtamtud, prošel Ježíš kolem Galilejského moře, vystoupil na horu a posadil se tam.',
        30: 'Tu k němu přišly veliké zástupy, které měly s sebou chromé, slepé, zmrzačené, němé a mnohé jiné. Položili mu je k nohám a on je uzdravil,',
        31: 'takže zástup užasl, když viděl, že němí mluví, zmrzačení jsou zdraví, chromí chodí a slepí vidí; i vzdali chválu ⌈Bohu Izraele⌉.',
        32: 'Ježíš si pak zavolal své učedníky a řekl: „Jsem hluboce pohnut nad tím zástupem, protože již tři dny zůstávají se mnou a nemají co jíst. A nechci je propustit hladové, aby nezemdleli na cestě.“',
        33: 'A učedníci mu řekli: „Kde vezmeme v pustině tolik chlebů, abychom nasytili takový zástup?“',
        34: 'Ježíš jim řekl: „Kolik máte chlebů?“Oni řekli: „Sedm a několik rybiček.“',
        35: 'Nařídil zástupu posadit se na zem;',
        36: 'vzal těch sedm chlebů a ty ryby, vzdal díky, rozlámal a dával učedníkům a učedníci zástupům.',
        37: 'Všichni pojedli a nasytili se; a sebrali sedm plných košů zbylých úlomků.',
        38: 'Těch, kteří jedli, bylo čtyři tisíce mužů kromě žen a dětí.',
        39: 'Potom zástupy propustil, vstoupil na loď a připlul na území Magadan.',
    },
    16: {
        1: 'I přistoupili k němu farizeové a saduceové a zkoušeli ho; chtěli, aby jim ukázal znamení z nebe.',
        2: 'On jim však odpověděl: „[Když nastane večer, říkáte: Bude pěkně, neboť se nebe červená.',
        3: 'A ráno: Dnes bude bouřka, neboť se červená zamračené nebe. Vzhled nebe tedy rozeznávat umíte, a znamení časů nikoli?]',
        4: 'Pokolení zlé a cizoložné vyhledává znamení, ale znamení mu nebude dáno, kromě znamení [proroka] Jonáše.“A zanechal je tam a odešel.',
        5: '[Jeho] učedníci přišli na druhou stranu a zapomněli vzít chleby.',
        6: 'Ježíš jim pověděl: „Dávejte si pozor a varujte se kvasu farizeů a saduceů!“',
        7: 'Oni se pak mezi sebou dohadovali a říkali: „ To proto, že jsme nevzali chleby.“',
        8: 'Ježíš to poznal a řekl: „Proč se mezi sebou dohadujete, malověrní, že nemáte chleby?',
        9: 'Ještě nerozumíte? Ani se nepamatujete na těch pět chlebů pro pět tisíc, a kolik nůší jste nasbírali?',
        10: 'Ani na těch sedm chlebů pro čtyři tisíce, a kolik košů jste nasbírali?',
        11: 'Jak to, že nerozumíte, že jsem k vám nemluvil o chlebech? Varujte se kvasu farizeů a saduceů!“',
        12: 'Tehdy pochopili, že neřekl, aby se varovali chlebového kvasu, nýbrž učení farizeů a saduceů.',
        13: 'Když Ježíš přišel do oblasti Cesareje Filipovy, ptal se svých učedníků: „Za koho lidé pokládají Syna člověka?“',
        14: 'Oni řekli: „Ti za Jana Křtitele, jiní za Eliáše, jiní za Jeremjáše nebo za jednoho z proroků.“',
        15: 'Řekl jim: „A za koho mě pokládáte vy?“',
        16: 'Šimon Petr odpověděl: „Ty jsi Mesiáš, Syn živého Boha.“',
        17: 'Ježíš mu ⌈na to⌉ řekl: „Blahoslavený jsi, Šimone Bar–Jona, protože ti to nezjevilo tělo a krev, ale můj Otec, který je v nebesích.',
        18: 'A já ti pravím, že ty jsi Petr, a na té skále vybuduji svou církev a brány podsvětí ji nepřemohou.',
        19: '[A] tobě dám klíče království Nebes, a cokoli svážeš na zemi, bude již svázáno v nebesích, a cokoli rozvážeš na zemi, bude již rozvázáno v nebesích.“',
        20: 'Tehdy přísně domluvil [svým] učedníkům, aby nikomu neřekli, že on je Mesiáš.',
        21: 'Od té doby Ježíš začal svým učedníkům ukazovat, že musí odejít do Jeruzaléma a mnoho vytrpět od starších, velekněží a učitelů Zákona, být zabit a třetího dne ⌈být vzkříšen⌉.',
        22: 'Petr si ho vzal stranou a začal ho kárat: „ Bůh tě chraň, Pane, to se ti určitě nestane!“',
        23: 'Ale on se otočil a řekl Petrovi: „Jdi ode mne, satane! Jsi mi kamenem úrazu, protože nemáš na mysli věci Boží, ale věci lidské.“',
        24: 'Tehdy Ježíš řekl svým učedníkům: „Chce–li kdo jít za mnou, ať zapře sám sebe, vezme svůj kříž a následuje mne.',
        25: 'Neboť kdo by chtěl svou duši zachránit, zahubí ji; kdo by však svou duši zahubil kvůli mně, nalezne ji.',
        26: 'Vždyť co člověku prospěje, získá–li celý svět, ale uškodí své duši? Anebo co dá člověk výměnou za svou duši?',
        27: 'Syn člověka má přijít v slávě svého Otce se svými anděly, a tehdy odplatí každému podle jeho jednání.',
        28: 'Amen, pravím vám, [že] někteří z těch, kdo zde stojí, určitě neokusí smrti, dokud nespatří Syna člověka přicházejícího ve ⌈své královské moci⌉.“',
    },
    17: {
        1: 'Po šesti dnech vzal Ježíš s sebou Petra, Jakuba a jeho bratra Jana a vyvedl je na vysokou horu, kde byli sami.',
        2: 'A byl před nimi proměněn. Jeho tvář zazářila jako slunce a jeho šaty zbělely jako světlo.',
        3: 'A hle, ukázal se jim Mojžíš a Eliáš a rozmlouvali s ním.',
        4: 'Petr ⌈na to⌉ Ježíšovi řekl: „Pane, je pro nás dobré tu být. Chceš–li, udělám tu tři stánky, tobě jeden, Mojžíšovi jeden a Eliášovi jeden.“',
        5: 'Když ještě mluvil, hle, zastínil je zářivý oblak a z oblaku se ozval hlas: „Toto je můj milovaný Syn, v němž jsem nalezl zalíbení; toho poslouchejte.“',
        6: 'Když to učedníci uslyšeli, padli na tvář a velmi se báli.',
        7: 'Ježíš k nim přistoupil, dotkl se jich a řekl: „Vstaňte a nebojte se.“',
        8: 'Když pozvedli oči, neviděli nikoho, jen samotného Ježíše.',
        9: 'A když sestupovali z hory, Ježíš jim přikázal: „Nikomu o tom vidění neříkejte, dokud Syn člověka nebude vzkříšen z mrtvých.“',
        10: '[Jeho] učedníci se ho zeptali: „Jak to, že učitelé Zákona říkají, že nejprve musí přijít Eliáš?“',
        11: 'On odpověděl: „Eliáš opravdu přichází a všechno obnoví.',
        12: 'Avšak pravím vám: Eliáš již přišel, a nepoznali ho, ale udělali s ním, co chtěli; tak bude od nich trpět i Syn člověka.“',
        13: 'Tehdy učedníci pochopili, že jim to řekl o Janu Křtiteli.',
        14: 'Když přišli k zástupu, přistoupil k němu jeden člověk a padl před ním na kolena',
        15: 'řka: „Pane, smiluj se nad mým synem, neboť je náměsíčný a ⌈zle trpí⌉; často totiž padá do ohně a často do vody.',
        16: 'A přivedl jsem ho k tvým učedníkům, ale nemohli ho uzdravit.“',
        17: 'Ježíš odpověděl: „Ach, pokolení nevěřící a zvrácené, jak dlouho ještě budu s vámi? Jak dlouho vás mám snášet? Při veďte ho sem ke mně!“',
        18: 'Ježíš mu pohrozil a démon od něho vyšel; a od té hodiny byl chlapec uzdraven.',
        19: 'V soukromí potom k Ježíšovi přistoupili učedníci a řekli: „Proč jsme ho nemohli vyhnat my?“',
        20: 'On jim řekl: „Pro vaši malověrnost! Amen, pravím vám, budete–li mít víru jako zrno hořčice, řeknete této hoře: Přejdi odtud tam, a přejde; a nic vám nebude nemožné.',
        21: '[Tento rod nevychází jinak než v modlitbě a půstu.] “',
        22: 'Když se zdržovali v Galileji, řekl jim Ježíš: „Syn člověka má být vydán do rukou lidí;',
        23: 'zabijí ho, ale třetí den ⌈bude vzkříšen⌉.“A oni se velmi zarmoutili.',
        24: 'Když přišli do Kafarnaum, přistoupili k Petrovi výběrčí dvojdrachem a řekli: „Copak váš Učitel neplatí dvojdrachmu?“',
        25: 'Řekl: „ Ale ano.“Jakmile vešel do domu, Ježíš ho předešel otázkou: „Co myslíš, Šimone? Od koho vybírají králové země poplatky a daň? Od svých synů, nebo od cizích?“',
        26: 'Když [Petr] řekl: „Od cizích“, pověděl mu Ježíš: „Synové jsou tedy svobodni.',
        27: 'Abychom je však nepohoršili, jdi k moři, hoď udici a vytáhni první rybu, která se vynoří. Až otevřeš její ústa, nalezneš statér; ten vezmi a dej jim za mne i za sebe.“',
    },
    18: {
        1: 'V tu hodinu přistoupili učedníci k Ježíšovi a říkali: „Kdo je tedy v království Nebes největší?“',
        2: '[Ježíš] přivolal dítě, postavil je doprostřed nich',
        3: 'a řekl: „Amen, pravím vám: Neobrátíte–li se a nebudete–li jako děti, jistě nevejdete do království Nebes.',
        4: 'Kdo se tedy pokoří jako toto dítě, ten bude největší v království Nebes.',
        5: 'A kdo přijme jedno takové dítě na základě mého jména, mne přijímá.“',
        6: '„Kdo by však ⌈svedl k hříchu ⌉ jednoho z těchto maličkých, kteří věří ve mne, pro toho by bylo lépe, aby mu na krk pověsili velký mlýnský kámen a potopili ho do mořské hlubiny.',
        7: 'Běda světu pro svody! Svody sice musí přijít, avšak běda tomu člověku, skrze kterého svod přichází!',
        8: 'Jestliže tě tvá ruka nebo tvá noha ⌈svádí k hříchu ⌉, utni ji a odhoď; lépe je pro tebe, abys vešel do života zmrzačený nebo chromý, než abys měl obě ruce nebo obě nohy, a byl uvržen do věčného ohně.',
        9: 'A jestliže tě svádí tvé oko, vyjmi je a odhoď; lépe je pro tebe, abys vešel do života jednooký, než abys měl obě oči, a byl uvržen do ohnivé Gehenny.“',
        10: '„Dávejte si pozor, abyste nepohrdli ani jedním z těchto maličkých. Neboť vám pravím, že jejich andělé v nebesích stále hledí na tvář mého Otce, který je v nebesích.',
        11: '[Vždyť Syn člověka přišel zachránit, co zahynulo.]',
        12: 'Co myslíte? Kdyby nějaký člověk měl sto ovcí a jedna z nich by zabloudila, nenechá těch devadesát devět na horách a nevydá se hledat tu, která bloudí?',
        13: 'A stane–li se, že ji nalezne, amen, pravím vám, že se z ní raduje víc než z těch devadesáti devíti, které nezabloudily.',
        14: 'Právě tak není vůle ⌈vašeho Otce⌉, který je v nebesích, aby zahynul jediný z těchto maličkých.“…',
        15: '„Jestliže tvůj bratr [proti tobě] zhřeší, jdi a pokárej ho ⌈mezi čtyřma očima⌉. Poslechne–li tě, získal jsi svého bratra.',
        16: 'Jestliže by však neposlechl, vezmi s sebou ještě jednoho nebo dva, aby ústy dvou nebo tří svědků byl potvrzen každý výrok.',
        17: 'Jestliže by je neposlechl, pověz to shromáždění, a jestliže by neposlechl ani shromáždění, ať je ti jako pohan a celník.“',
        18: '„Amen, pravím vám, cokoli svážete na zemi, bude již svázáno v nebi, a cokoli rozvážete na zemi, bude již rozvázáno v nebi.',
        19: '[Amen,] opět vám pravím: Shodnou–lise dva z vás na zemi v jakékoli věci, o niž požádají, stane se jim od mého Otce, který je v nebesích.',
        20: 'Neboť kde jsou dva nebo tři shromážděni ⌈v mé jméno⌉, tam jsem já uprostřed nich.“',
        21: 'Tehdy přistoupil ⌈Petr a řekl mu⌉: „Pane, kolikrát mám odpustit svému bratru, když proti mně zhřeší? Až sedmkrát?“',
        22: 'Ježíš mu řekl: „Pravím ti, ne sedmkrát, ale až sedmdesátkrát sedm krát.“',
        23: '„Proto je království Nebes podobné králi, který chtěl provést vyúčtování se svými otroky.',
        24: 'Když začal účtovat, přivedli mu jednoho, který mu dlužil deset tisíc talentů.',
        25: 'Protože však neměl čím zaplatit, rozkázal ho [jeho] pán prodat i se ženou a dětmi i se vším, co má, aby tak splatil svůj dluh.',
        26: '[Onen] otrok padl na zem, klaněl se mu a říkal: Měj se mnou trpělivost, [pane,] a všechno ti vrátím!',
        27: 'I slitoval se pán onoho otroka, propustil ho a dluh mu odpustil.',
        28: 'Ale když onen otrok vyšel, nalezl jednoho ze svých spoluotroků, který mu byl dlužen sto denárů; popadl ho a začal ho škrtit, říkaje: Zaplať, co [mi] dlužíš!',
        29: 'Jeho spoluotrok padl [k jeho nohám] a prosil ho: Měj se mnou trpělivost, a zaplatím ti.',
        30: 'On však nechtěl, ale šel a uvrhl ho do vězení, dokud nezaplatí dluh.',
        31: 'Když jeho spoluotroci uviděli, co se přihodilo, velmi se zarmoutili; šli a oznámili svému pánu všechno, co se stalo.',
        32: 'Tehdy si ho jeho pán zavolal a řekl mu: Otroku zlý, celý ten dluh jsem ti odpustil, protože jsi mě poprosil.',
        33: 'Neměl ses také ty smilovat nad svým spoluotrokem, jako jsem se i já smiloval nad tebou?',
        34: 'A jeho pán se rozhněval a předal ho mučitelům, dokud [mu] nezaplatí celý dluh.',
        35: 'Tak i můj nebeský Otec učiní vám, jestliže ze srdce neodpustíte každý svému bratru [jeho přestoupení].“',
    },
    19: {
        1: 'A stalo se, že když Ježíš dokončil tato slova, odebral se z Galileje a přišel na území Judska za Jordán.',
        2: 'Šly za ním velké zástupya on je tam uzdravil.',
        3: 'Přistoupili k němu farizeové, aby ho pokoušeli. Říkali: „Je dovoleno, aby [člověk] propustil svou ženu z jakéhokoli důvodu?“',
        4: 'On [jim] odpověděl: „Nečetli jste, že ten, který stvořil člověka, od počátku učinil je jako muže a ženu?',
        5: 'A řekl: Proto člověk opustí otce i matku a přilne ke své ženě a ti dva budou jedno tělo,',
        6: 'takže již nejsou dva, ale jedno tělo. Co tedy Bůh spojil, ať člověk neodděluje!“',
        7: 'Řekli mu: „Proč tedy Mojžíš nařídil dát ženě rozlukový list a propustit [ji]?“',
        8: 'Řekl jim: „Pro tvrdost vašeho srdce vám Mojžíš dovolil propouštět vaše ženy, od počátku však tomu tak nebylo.',
        9: 'Pravím vám, že kdo by propustil svou ženu, ⌈ pokud by to ne bylo na základě⌉ smilstva, a oženil se s jinou, cizoloží; [a kdo by se s propuštěnou oženil, cizoloží].“',
        10: '[Jeho] učedníci mu řekli: „Jestliže je to mezi mužem a ženou takové, je lépe se neženit.“',
        11: 'On jim řekl: „Ne všichni chápou [toto] slovo, ale jen ti, kterým je to dáno.',
        12: 'Jsou totiž eunuchové, kteří se už takto narodili z matčina lůna; a jsou eunuchové, které učinili eunuchy lidé; a jsou eunuchové, kteří se sami stali eunuchy pro království Nebes. Kdo může chápat, chápej.“',
        13: 'Tehdy k němu přinesli děti, aby na ně vložil ruce a pomodlil se; ale učedníci je pokárali.',
        14: 'Ježíš však řekl: „Nechte děti a nebraňte jim přijít ke mně, neboť takovým patří království Nebes.“',
        15: 'A vložil na ně ruce a šel odtamtud.',
        16: 'A hle, přistoupil k němu jeden člověk a řekl: „Učiteli, co dobrého ⌈mám učinit⌉, abych obdržel věčný život?“',
        17: 'On mu řekl: „⌈Proč se mě ptáš na dobré? Jeden je dobrý [: Bůh] ⌉. Chceš–li vstoupit do života, zachovej přikázání!“',
        18: 'Řekl mu: „Která?“Ježíš řekl: „Nezavraždíš, nezcizoložíš, neukradneš, nevydáš křivé svědectví,',
        19: 'cti otce a matku, budeš milovat svého bližního jako sebe.“',
        20: 'Mladík mu řekl: „To všechno zachovávám [od svého mládí]. Co mi ještě schází?“',
        21: 'Ježíš mu řekl: „Chceš–li být dokonalý, jdi, prodej svůj majeteka dej chudým, a budeš mít poklad v nebesích; pak přijď a následuj mne.“',
        22: 'Když mladík uslyšel [toto] slovo, odešel zarmoucen, neboť měl mnoho majetku.',
        23: 'Ježíš řekl svým učedníkům: „Amen, pravím vám, že bohatý do království Nebes vejde těžko.',
        24: 'Opět vám pravím, je snadnější, aby velbloud prošel uchem jehly, než aby bohatý vešel do Božího království.“',
        25: 'Když to učedníci uslyšeli, byli velice ohromeni a říkali: „Kdo tedy může být zachráněn?“',
        26: 'Ježíš na ně pohleděl a řekl jim: „U lidí je to nemožné, ale u Boha je možné všechno.“',
        27: '⌈Na to⌉ mu řekl Petr: „Hle, my jsme opustili všechno a vydali se za tebou. Co tedy budeme mít?“',
        28: 'Ježíš jim řekl: „Amen, pravím vám, ⌈až se Syn člověka při obnovení všech věcí posadí na trůn své slávy, usednete také vy, kteří jste mne následovali,⌉ na dvanáct trůnů a budete soudit dvanáct kmenů Izraele.',
        29: 'A každý, kdo opustil domy nebo bratry nebo sestry nebo otce nebo matku [nebo ženu] nebo děti nebo pole pro mé jméno, vezme stokrát víc a získá věčný život.',
        30: 'Mnozí první budou poslední a poslední první.“',
    },
    20: {
        1: '„Neboť království Nebes je podobné hospodáři, který časně zrána vyšel najmout dělníky na svou vinici.',
        2: 'Smluvil s dělníky denár na den a poslal je na vinici.',
        3: 'A když vyšel kolem deváté hodiny, spatřil jiné, jak stojí nečinně na tržišti,',
        4: 'a řekl jim: Jděte i vy na vinici a dám vám, co bude spravedlivé.',
        5: 'Oni šli. Opět vyšel kolem ⌈dvanácté a třetí hodiny⌉ odpoledne a učinil stejně.',
        6: 'Vyšel kolem páté hodiny a našel jiné, jak tam stojí, a řekl jim: Proč tu stojíte celý den nečinně?',
        7: 'Řekli mu: Protože nás nikdo nenajal. Řekl jim: Jděte i vy na [mou] vinici [a dostanete, co bude spravedlivé].',
        8: 'Když nastal večer,řekl pán vinice svému správci: Zavolej dělníky a vyplať jim mzdu, počna od posledních až k prvním.',
        9: 'Přišli ti, kteří byli najati okolo páté hodiny, a každý dostal denár.',
        10: 'Když přišli ti první, myslili, že dostanou víc; ale i oni dostali po denáru.',
        11: '⌈Vzali si jej, ale reptali⌉ proti hospodáři:',
        12: 'Tito poslední dělali jedinou hodinu a postavil jsi je na roveň nám, kteří jsme nesli tíhu dne a vedro!',
        13: 'On však jednomu z nich odpověděl: Příteli, nekřivdím ti! Nesmluvil jsi se mnou denár za den?',
        14: 'Vezmi, co ti patří, a odejdi! Chci i tomu poslednímu dát jako tobě.',
        15: 'Nemám [snad] právo udělat si ve svých záležitostech, co chci? Anebo závidíš, že já jsem dobrý?',
        16: 'Tak budou poslední první a první poslední. [Neboť je mnoho pozvaných, ale málo vybraných.] “',
        17: 'Když Ježíš vystupoval do Jeruzaléma, vzal si stranou dvanáct [učedníků] a cestou jim řekl:',
        18: '„Hle, vystupujeme do Jeruzaléma a Syn člověka bude vydán velekněžím a učitelům Zákona. Odsoudí ho k smrti',
        19: 'a vydají pohanům, aby se mu vysmáli, zbičovali ho a ukřižovali; a třetího dne bude vzkříšen.“',
        20: 'Tehdy k němu přistoupila matka synů Zebedeových se svými syny, klaněla se mu a o něco ho žádala.',
        21: 'On jí řekl: „Co chceš?“Řekla mu: „Ustanov, aby ve tvém království tito dva moji synové usedli jeden po tvé pravici a druhý po tvé levici.“',
        22: 'Ježíš odpověděl: „Nevíte, co žádáte. Můžete pít kalich, který mám pít já?“Řekli mu: „Můžeme.“',
        23: 'Řekl jim: „Můj kalich sice pít budete, ale není mou věcí, abych dal někomu usednout po mé pravici a po mé levici, neboť tam usednou ti, pro které je to připraveno od mého Otce.“',
        24: 'Když to uslyšelo těch deset, rozhořčili se na ty dva bratry.',
        25: 'Ježíš si je zavolal a řekl: „Víte, že vládci národů panují nad nimi a velcí nad nimi ⌈vykonávají svou svrchovanou moc⌉.',
        26: 'Mezi vámi tomu tak nebude; ale kdo by se chtěl mezi vámi stát velkým, bude vaším služebníkem;',
        27: 'a kdo by chtěl být mezi vámi první, bude vaším otrokem.',
        28: 'Stejně jako Syn člověka nepřišel, aby si nechal posloužit, ale aby posloužil a dal svůj život jako výkupné za mnohé.“',
        29: 'Když vycházeli z Jericha, vydal se za ním velký zástup.',
        30: 'A hle, dva slepí seděli u cesty; jakmile uslyšeli, že jde kolem Ježíš, vykřikli: „Smiluj se nad námi, [Pane], synu Davidův!“',
        31: 'Zástup jim přísně domluvil, aby utichli. Oni však vykřikli ještě silněji: „Smiluj se nad námi, Pane, synu Davidův!“',
        32: 'Ježíš se zastavil, zavolal je a řekl: „Co chcete, abych vám učinil?“',
        33: 'Řekli mu: „Pane, ať se nám otevřou oči!“',
        34: 'Ježíš byl hluboce pohnut, dotkl se jejich očí, a hned prohlédli a šli za ním.',
    },
    21: {
        1: 'Když se přiblížili k Jeruzalému a přišli do Betfage na Olivové hoře, poslal Ježíš dva učedníky',
        2: 'a řekl jim: „Jděte do protější vesnice a hned naleznete uvázanou oslici a s ní oslátko. Odvažte je a přiveďte ke mně.',
        3: 'A kdyby vám někdo něco řekl, povězte: ⌈ Pán je potřebuje a hned je pošle. ⌉“',
        4: 'Toto [všechno] se stalo, aby se naplnilo, co bylo řečeno skrze proroka:',
        5: 'Řekněte dceři siónské: Hle, tvůj král k tobě přichází, tichý a sedící na oslici a [na] oslátku, synu té pod jhem.',
        6: 'Učedníci šli a učinili, jak jim Ježíš nařídil.',
        7: 'Přivedli oslici i oslátko, položili na ně pláště a on se na ně posadil.',
        8: 'Mohutný zástup rozprostřel své pláště na cestu, jiní zase odsekávali větve ze stromů a stlali je na cestu.',
        9: 'Zástupy, které šly před ním, i ty, které ho doprovázely, křičely: „Hosana synu Davidovu! Požehnaný, který přichází ve jménu Pána! Hosana na výsostech!“',
        10: 'Když vjel do Jeruzaléma, celé město se zatřáslo a říkalo: „Kdo to je?“',
        11: 'Zástupy říkaly: „To je ⌈prorok Ježíš, ten⌉ z Nazareta v Galileji.“',
        12: 'Ježíš vstoupil do [Božího] chrámu a vyhnal všechny, kteří v chrámě prodávali a kupovali, zpřevracel stoly směnárníků i sedadla prodavačů holubů',
        13: 'a řekl jim: „Je napsáno: Můj dům bude nazván domem modlitby, ale vy z něj děláte jeskyni lupičů.“',
        14: 'A přistoupili k němu v chrámě ⌈slepí a chromí⌉, a uzdravil je.',
        15: 'Když velekněží a učitelé Zákona spatřili ty ⌈podivuhodné věci⌉, které učinil, i děti volající v chrámě: „Hosana synu Davidovu“, byli pobouřeni',
        16: 'a řekli mu: „Slyšíš, co tihle říkají?“Ježíš jim řekl: „Ano. Nikdy jste nečetli: Z úst nemluvňat a kojenců sis připravil chválu?“',
        17: 'I nechal je a vyšel ven z města do Betanie, kde přenocoval.',
        18: 'Když se časně ráno vracel do města, dostal hlad.',
        19: 'Spatřil u cesty fíkovník a šel k němu, ale nenašel na něm nic, jen pouhé listí. Řekl mu: „Ať se z tebe již nikdy ovoce neurodí!“A fíkovník ihned uschl.',
        20: 'Když to učedníci uviděli, užasli se a říkali: „Jak ten fíkovník hned uschl!“',
        21: 'Ježíš jim ⌈na to⌉ řekl: „Amen, pravím vám, budete–li mít víru a nezapochybujete–li, učiníte nejen to, co jsem učinil s fíkovníkem, ale kdybyste i této hoře řekli: Zvedni se a vrhni se do moře, stane se to.',
        22: 'A všechno, oč byste v modlitbě požádali, ⌈budete–li věřit⌉, dostanete.“',
        23: 'Když přišel do chrámu a vyučoval, přistoupili k němu velekněží a starší lidu a řekli: „⌈V jaké pravomoci⌉ činíš tyto věci? Kdo ti dal tuto pravomoc?“',
        24: 'Ježíš jim odpověděl: „I já se vás zeptám na jednu věc. Jestliže mi to řeknete, i já vám povím, v jaké pravomoci tyto věci činím.',
        25: 'Odkud byl křest Janův? Z nebe, či z lidí?“Oni se mezi sebou dohadovali: „Řekneme–li z nebe, řekne nám: Proč jste mu tedy neuvěřili?',
        26: 'Řekneme–li však z lidí, obáváme se zástupu, neboť všichni mají Jana za proroka.“',
        27: 'Odpověděli Ježíšovi: „Nevíme.“A on jim řekl: „Ani já vám nepovím, v jaké pravomoci tyto věci činím.“',
        28: '„Co myslíte? Jeden člověk měl dva syny. Přistoupil k prvnímu a řekl: Synu, jdi dnes pracovat na [mou] vinici.',
        29: 'On odpověděl: Nechci. Ale potom toho litoval a šel.',
        30: 'Přistoupil k druhému a řekl totéž. On odpověděl: Ano, pane, ale nešel.',
        31: 'Který z těch dvou vykonal otcovu vůli?“Řekli: „Ten první.“Ježíš jim řekl: „Amen, pravím vám, že celníci a nevěstky vás předcházejí do Božího království.',
        32: 'Neboť Jan k vám přišel cestou spravedlnosti, ale neuvěřili jste mu. Celníci a nevěstky mu však uvěřili. A když jste to uviděli, ani potom jste toho nelitovali, abyste mu uvěřili.“',
        33: '„Poslyšte jiné podobenství: Byl jeden člověk, hospodář, který vysadil vinici, obehnal ji zdí, vykopal v ní lis a vystavěl věž; pak ji pronajal vinařům a odcestoval.',
        34: 'Když se přiblížil čas úrody, poslal své otroky k vinařům, aby pře vzali jeho úrodu.',
        35: 'Ale vinaři jeho otroky chytili, jednoho zbili, druhého zabili, dalšího ukamenovali.',
        36: 'Znovu poslal jiné otroky, bylo jich ještě více než těch prvních, ale učinili jim totéž.',
        37: 'Naposled k nim poslal svého syna a řekl: ⌈Zastydí se před mým synem.⌉',
        38: 'Když však vinaři uviděli syna, řekli si: To je dědic. Pojďte, zabijme ho a zmocněme se jeho dědictví!',
        39: 'I chytili ho, vyhodili ven z vinice a zabili.',
        40: 'Když tedy přijde pán vinice, co učiní oněm vinařům?“',
        41: 'Řekli mu: „Ty zlé zle zahubí a vinici pronajme jiným vinařům, kteří mu budou úrodu odevzdávat v určených časech.“',
        42: 'Ježíš jim řekl: „Copak jste nikdy nečetli v Písmech: Kámen, který stavitelé po prozkoumání zavrhli, se stal hlavou úhlu. Od Pána se to stalo a je to podivuhodné v našich očích?',
        43: 'Proto vám pravím, že vám bude Boží království odňato a bude dáno národu, který přináší jeho úrodu.',
        44: 'Kdo padne na ten kámen, roztříští se, a na koho padne, toho rozdrtí.“',
        45: 'Když velekněží a farizeové uslyšeli tato jeho podobenství, poznali, že mluví o nich.',
        46: 'Chtěli se ho zmocnit, ale báli se zástupů, protože ty ho měly za proroka.',
    },
    22: {
        1: 'A Ježíš k nim znovu promluvil v podobenstvích:',
        2: '„Království Nebes ⌈je podobné⌉ králi, který vystrojil svatbu svému synu.',
        3: 'A poslal své otroky, aby zavolali pozvané na svatbu; ale ti nechtěli přijít.',
        4: 'Poslal znovu jiné otroky ⌈se slovy⌉: Řekněte pozvaným: Hle, přichystal jsem svou hostinu, moji býci a krmný dobytek jsou poraženi, všechno je připraveno, přijďte na svatební hostinu.',
        5: 'Ale oni nedbali a odešli, jeden na své pole, jiný za svým obchodem.',
        6: 'Ostatní se zmocnili jeho otroků, ztýrali je a zabili.',
        7: '⌈Král se rozhněval⌉, poslal svá vojska, zahubil ony vrahy a jejich město vypálil.',
        8: 'Potom řekl svým otrokům: Svatba je sice připravena, ale pozvaní jí nebyli hodni.',
        9: 'Jděte tedy na křižovatky cest a každého, koho naleznete, pozvěte na svatební hostinu.',
        10: 'I vyšli ti otroci na cesty a shromáždili všechny, které nalezli, zlé i dobré. A ⌈svatební síň⌉ se naplnila stolovníky.',
        11: 'Když král vstoupil, aby se na stolovníky podíval, spatřil tam člověka, který na sobě neměl svatební šat.',
        12: 'I řekl mu: Příteli, jak jsi sem vešel bez svatebního roucha? A on oněměl.',
        13: 'Tehdy řekl král služebníkům: Svažte mu nohy a ruce a vyhoďte ho do nejzazší temnoty; tam bude pláč a skřípění zubů.',
        14: 'Neboť je mnoho pozvaných, ale málo vybraných.“',
        15: 'Tehdy farizeové šli a poradili se, jak by ho chytili za slovo.',
        16: 'A poslali k němu své učedníky spolu s herodiány, kteří řekli: „Učiteli, víme, že jsi pravdivý a Boží cestě učíš podle pravdy. A nedbáš na nikoho, neboť ⌈nebereš ohled na postavení člověka⌉.',
        17: 'Řekni nám tedy, co myslíš: Je dovoleno dát daň císaři, nebo ne?“',
        18: 'Ježíš poznal jejich ⌈zlý úmysl⌉ a řekl: „Proč mne zkoušíte, pokrytci?',
        19: 'Ukažte mi peníz daně.“Přinesli mu denár.',
        20: 'Řekl jim: „Čí je ten obraz a nápis?“',
        21: 'Odpověděli mu: „Císařův.“Tu jim řekl: „Co je tedy císařovo, odevzdejte císaři, a co je Boží, Bohu.“',
        22: 'Když to uslyšeli, užasli, nechali ho a odešli.',
        23: 'V ten den k němu přišli saduceové, kteří říkají, že není vzkříšení, a zeptali se ho:',
        24: '„Učiteli, Mojžíš řekl: Zemře–li někdo bezdětný, jeho bratr si podle řádu švagrovství vezme jeho ženu a svému bratrovi ⌈vzbudí potomka⌉.',
        25: 'U nás bylo sedm bratrů. První se oženil a zemřel; a protože neměl potomka, zanechal svou ženu svému bratrovi.',
        26: 'Stejně i druhý a třetí, až do sedmého.',
        27: 'Poslední ze všech zemřela ta žena.',
        28: 'Kterému z těch sedmi bude tedy ta žena patřit při vzkříšení? Vždyť ji měli všichni.“',
        29: 'Ježíš jim odpověděl: „Bloudíte, protože neznáte Písma ani Boží moc.',
        30: 'Při vzkříšení se totiž lidé nežení ani nevdávají, ale jsou jako [Boží] andělé v nebi.',
        31: 'Pokud jde o vzkříšení mrtvých, nečetli jste, co vám bylo od Boha řečeno slovy:',
        32: 'Já jsem Bůh Abrahamův, Bůh Izákův a Bůh Jákobův? [Bůh] není Bohem mrtvých, ale živých.“',
        33: 'Když to zástupy uslyšely, byly ohromeny jeho učením.',
        34: 'Když farizeové uslyšeli, že umlčel saduceje, sešli se spolu',
        35: 'a jeden z nich, [zákoník], ho chtěl zkoušet a zeptal se:',
        36: '„Učiteli, které přikázání je v Zákoně největší?“',
        37: 'On mu řekl: „ Miluj Pána, svého Boha, celým svým srdcem, celou svou duší a celou svou myslí.',
        38: 'To je největší a první přikázání.',
        39: 'Druhé je mu podobné: Miluj svého bližního jako sebe samého.',
        40: 'Na těchto dvou přikázáních spočívá celý Zákon a Proroci.“',
        41: 'Když se farizeové shromáždili, Ježíš se jich zeptal:',
        42: '„Co si myslíte o Mesiáši? Čí je syn?“Řekli mu: „Davidův.“',
        43: 'Řekl jim: „Jak to tedy, že ho David v Duchunazývá Pánem, když praví:',
        44: 'Řekl Pán mému Pánu: Seď po mé pravici, dokud tvé nepřátele nepoložím ⌈za podnož tvých nohou⌉?',
        45: 'Jestliže ho tedy David nazývá Pánem, jakpak je jeho synem?“',
        46: 'A nikdo mu nemohl odpovědět ani slovo; od toho dne se ho již nikdo neodvážil zeptat.',
    },
    23: {
        1: 'Tehdy Ježíš promluvil k zástupům a ke svým učedníkům:',
        2: '„Na stolci Mojžíšově usedli učitelé Zákona a farizeové.',
        3: 'Proto udělejte a zachovávejte všechno, co by vám řekli, avšak podle jejich skutků nečiňte; neboť mluví, ale nečiní.',
        4: 'Svazují těžká [a neúnosná] břemena a vkládají je lidem na ramena, ale sami jimi nechtějí hnout ani prstem.',
        5: 'A všecky své skutky dělají proto, aby je lidé viděli. Rozšiřují své ⌈modlitební řemínky⌉ a prodlužují třásně [svých oděvů],',
        6: 'mají rádi přední místa na hostinách a přední sedadla v synagogách,',
        7: 'pozdravy na tržištích a jsou rádi, když je lidé oslovují Rabbi [Rabbi].',
        8: 'Vy se však nenechte nazývat Rabbi, neboť jediný je váš Učitel, vy pak všichni jste bratři.',
        9: 'A nikoho nenazývejte na zemi svým Otcem, neboť jediný je váš Otec, ten nebeský.',
        10: 'Ani se nenechte nazývat Vůdci, neboť váš Vůdce je jeden, Mesiáš.',
        11: 'Ale největší z vás bude vaším služebníkem.',
        12: 'Kdo se bude povyšovat, bude ponížen, a kdo se poníží, bude povýšen.“',
        13: '„Běda vám, učitelé Zákona a farizeové, pokrytci, protože zavíráte království Nebes před lidmi; sami totiž nevstupujete, a ⌈těm, kdo by chtěli vstoupit,⌉ vstoupit nedovolujete.',
        14: '[Běda vám, učitelé Zákona a farizeové, pokrytci, protože vyjídáte domy vdov a okázale dlouho se modlíte; proto vezmete těžší odsouzení.] “',
        15: '„Běda vám, učitelé Zákona a farizeové, pokrytci, protože obcházíte moře i souš, abyste získali jednoho proselytu; a když se jím stane, děláte z něho syna Gehenny, dvakrát horšího, než jste sami.“',
        16: '„Běda vám, slepí vůdcové! Říkáte: Kdo by učinil přísahu při svatyni, nic to neznamená; ale kdo by učinil přísahu při zlatu svatyně, je vázán.',
        17: 'Blázni a slepci, co je větší: zlato, nebo svatyně, která to zlato posvětila?',
        18: 'A kdo by učinil přísahu při oltáři, nic to neznamená, ale kdo by vyslovil přísahu při daru, který je na něm, je vázán.',
        19: '[Blázni a] slepci, co je větší: dar, nebo oltář, který ten dar posvěcuje?',
        20: 'Kdo tedy přísahá při oltáři, přísahá při něm i při všem, co je na něm.',
        21: 'A kdo přísahá při svatyni, přísahá při ní i při Tom, kdo v ní přebývá.',
        22: 'A kdo přísahá při nebi, přísahá při trůnu Božím i při Tom, který na něm sedí.“',
        23: '„Běda vám, učitelé Zákona a farizeové, pokrytci, protože dáváte desátky z máty, kopru a kmínu, ale zanedbali jste závažnější věci Zákona: právo, milosrdenství a věrnost. Toto bylo třeba udělat a tamto nezanedbávat.',
        24: 'Slepí vůdcové! Cedíte komára, ale velblouda polykáte.“',
        25: '„Běda vám, učitelé Zákona a farizeové, pokrytci, protože čistíte číše a mísy zvnějšku, ale uvnitř jsou plné chamtivosti a nezdrženlivosti.',
        26: 'Slepý farizeji! Napřed vyčisti vnitřek číše [a mísy], aby se stal čistým i jejich zevnějšek.“',
        27: '„Běda vám, učitelé Zákona a farizeové, pokrytci, protože se podobáte obíleným hrobům, které se zvenčí zdají pěkné, ale uvnitř jsou plné kostí mrtvých a veškeré nečistoty.',
        28: 'Tak i vy se navenek zdáte lidem spravedliví, ale uvnitř jste plni pokrytectví a bezzákonnosti.“',
        29: '„Běda vám, učitelé Zákona a farizeové, pokrytci, protože stavíte náhrobky prorokům a zdobíte pomníky spravedlivých',
        30: 'a říkáte: Kdybychom žili ve dnech svých otců, neměli bychom s nimi ⌈na prolévání krve⌉ proroků podíl.',
        31: 'Tak svědčíte sami proti sobě, že jste synové těch, kteří proroky zavraždili.',
        32: 'I vy naplňte míru svých otců!',
        33: 'Hadi, ⌈plemeno zmijí⌉! Jak uniknete trestu Gehenny?',
        34: 'Hle, proto já k vám posílám proroky a moudré muže i ⌈učitele Zákona⌉; některé z nich zabijete a ukřižujete, některé z nich budete bičovat ve svých synagogách a pronásledovat od města k městu,',
        35: 'aby na vás padla všechna spravedlivá krev vylévaná na zemi, od krve spravedlivého Ábela až po krev Zachariáše, syna Barachiášova, kterého jste zavraždili mezi svatyní a oltářem.',
        36: 'Amen, pravím vám, to všechno přijde na toto pokolení.“',
        37: '„Jeruzaléme, Jeruzaléme, který zabíjíš proroky a kamenuješ ty, kteří jsou k tobě posláni, kolikrát jsem chtěl shromáždit tvé děti, tak jako slepice shromažďuje svá kuřata pod křídla, ale nechtěli jste.',
        38: 'Hle, váš dům se vám zanechává [pustý].',
        39: 'Neboť pravím vám, od nynějška mne již neuvidíte, dokud neřeknete: Požehnaný, který přichází ve jménu Pána! “',
    },
    24: {
        1: 'Ježíš vyšel z chrámu a odcházel. Tu přistoupili jeho učedníci, aby mu ukázali na chrámové stavby.',
        2: 'Ale on jim ⌈na to⌉ řekl: „Vidíte to všechno? Amen, pravím vám, jistě zde nezůstane kámen na kameni, který nebude stržen.“',
        3: 'Když seděl na Olivové hoře, v soukromí k němu přistoupili učedníci a říkali: „Řekni nám, kdy to bude a jaké bude znamení tvého příchodu a skonání věku?“',
        4: 'Ježíš jim odpověděl: „Dávejte si pozor, aby vás někdo nesvedl.',
        5: 'Neboť mnozí přijdou ⌈v mém jménu⌉ a budou říkat: Já jsem Kristus a svedou mnohé.',
        6: 'Budete slýchat o válkách a uslyšíte válečné zvěsti. Dejte si pozor, neděste se. To [všechno] musí nastat, ale to ještě není konec.',
        7: 'Povstane totiž národ proti národu a království proti království, budou hladomory a země třesení na různých místech.',
        8: 'Ale to všechno bude počátek porodních bolestí.',
        9: 'Pak vás budou vydávat do soužení a budou vás zabíjet; a všechny národy vás budou nenávidět pro mé jméno.',
        10: 'A tehdy ⌈mnohým to bude kamenem úrazu,⌉ budou se navzájem zrazovat a jeden druhého nenávidět.',
        11: 'Také povstanou mnozí lživí proroci a mnohé svedou.',
        12: 'A protože vzroste bezzákonnost, ochladne láska mnohých.',
        13: 'Ten však, kdo vytrvá do konce, bude zachráněn.',
        14: 'Toto evangelium království bude vyhlášeno po celém světě na svědectví všem národům. A tehdy přijde konec.“',
        15: '„Když pak uvidíte ohavnost zpustošení, o níž mluvil prorok Daniel, jak stojí na svatém místě -- kdo čte, ať rozumí --',
        16: 'tehdy ti, kdo budou v Judsku, ať utíkají do hor.',
        17: 'Kdo bude na střeše, ať nesestupuje, aby si vzal věci ze svého domu.',
        18: 'A kdo bude na poli, ať se nevrací zpátky, aby si vzal svůj plášť.',
        19: 'Běda těhotným a kojícím v oněch dnech!',
        20: 'Modlete se, aby k vašemu útěku nedošlo v zimě nebo v sobotu.',
        21: 'Neboť tehdy bude velké soužení, jaké nenastalo od počátku světa až do nynějška, a nikdy již nenastane.',
        22: 'A kdyby nebyly ty dny zkráceny, nebylo by zachráněno žádné tělo; ale kvůli vyvoleným budou ony dny zkráceny.',
        23: 'Tehdy, když by vám někdo řekl: Hle, zde je Kristus!, nebo: Je zde!, nevěřte.',
        24: 'Povstanou totiž falešní kristové a falešní proroci a budou ukazovat veliká znamení a divy, že by, kdyby to bylo možné, svedli i vyvolené.',
        25: 'Hle, všechno jsem vám řekl předem.',
        26: 'Řeknou–li vám tedy: Hle, je v pustině, nevycházejte; hle, v úkrytech, nevěřte!',
        27: 'Neboť jako když blesk vychází od východu a je vidět až na západ, tak bude [i] příchod Syna člověka.',
        28: 'Kdekoli je mrtvola, tam se shromáždí supi.“',
        29: '„Ihned po soužení oněch dnů se zatmí slunce a měsíc nebude vydávat svou zář, hvězdy budou padat z nebe a mocnosti nebes se zatřesou.',
        30: 'Potom se ukáže znamení Syna člověka na nebi, a tehdy se budou bít v prsa všechny kmeny země. A uvidí Syna člověka přicházejícího na nebeských oblacích s mocí a velikou slávou.',
        31: 'A pošle své anděly s mohutným [zvukem] polnice a ti shromáždí jeho vyvolené ze čtyř větrů, od jednoho nejzazšího konce nebes až k jejich druhému nejzazšímu konci.“',
        32: '„Od fíkovníku se naučte podobenství: Když již jeho větev změkne a vyhání listy, víte, že léto je blízko.',
        33: 'Tak i vy, až toto všechno uvidíte, vězte, že je to blízko, přede dveřmi.',
        34: 'Amen, pravím vám, že určitě nepomine toto pokolení, dokud se toto všechno nestane.',
        35: 'Nebe a země pominou, ale má slova jistě nepominou.“',
        36: '„O tom dni a hodině nikdo neví, ani andělé nebes, [ani Syn,] jenom sám Otec.',
        37: 'Neboť jak tomu bylo za dnů Noe, tak tomu bude [i] při příchodu Syna člověka.',
        38: 'Jako totiž v oněch dnech před potopou jedli, pili, ženili se a vdávaly, až do dne, kdy Noe vešel do korábu,',
        39: 'a nic nepoznali, dokud ne přišla potopa a všechny ne smetla, takový bude i příchod Syna člověka.',
        40: 'Tehdy budou dva na poli, jeden bude vzat a druhý bude zanechán.',
        41: 'Dvě budou mlít na obilném mlýnku, jedna bude vzata a druhá bude zanechána.',
        42: 'Bděte tedy, protože nevíte, v který den váš Pán přijde.',
        43: 'To však vězte, že kdyby hospodář věděl, v kterou noční hlídku přijde zloděj, zůstal by vzhůru a nedovolil by mu prokopat se do domu.',
        44: 'Proto i vy buďte připraveni, protože neznáte hodinu, v níž přijde Syn člověka.“',
        45: '„Kdo je tedy věrný a rozumný otrok, jehož pán ustanovil nad svou čeledí, aby jí dával pokrm v pravý čas?',
        46: 'Blahoslavený ten otrok, kterého jeho pán po svém příchodu nalezne, že tak činí.',
        47: 'Amen, pravím vám, že ho ustanoví nade vším svým majetkem.',
        48: 'Kdyby si však onen zlý otrok ve svém srdci řekl: Můj pán ⌈dlouho nepřichází⌉',
        49: 'a začal by bít své spoluotroky, jíst a pít s opilci,',
        50: 'přijde pán onoho otroka v den, kdy to nečeká, a v hodinu, kterou nezná.',
        51: 'Oddělí ho a určí mu úděl s pokrytci. Tam bude pláč a skřípění zubů.“',
    },
    25: {
        1: '„Tehdy bude království Nebes podobné deseti pannám, které vzaly své lampy a vyšly naproti ženichovi.',
        2: 'Pět z nich bylo pošetilých a pět rozumných.',
        3: 'Pošetilé vzaly [své] lampy, ale nevzaly s sebou olej.',
        4: 'Rozumné však se svými lampami vzaly i olej v nádobkách.',
        5: 'Když ženich dlouho nepřicházel, začaly všechny podřimovat a usnuly.',
        6: 'Uprostřed noci se však ozval křik: Hle, ženich! Vyjděte mu vstříc!',
        7: 'Tehdy všechny panny vstaly a daly své lampy do pořádku.',
        8: 'Pošetilé řekly rozumným: Dejte nám ze svého oleje, neboť naše lampy dohasínají!',
        9: 'Ale rozumné odpověděly: Ne, nemuselo by vystačit pro nás i pro vás. Jděte raději k prodavačům a kupte si!',
        10: 'Zatímco odcházely, aby nakoupily olej, přišel ženich, a ty, které byly připravené, s ním vešly na svatební hostinu; a dveře byly zavřeny.',
        11: 'Později přišly i ostatní panny a říkaly: Pane, pane, otevři nám!',
        12: 'Ale on odpověděl: Amen, pravím vám, neznám vás.',
        13: 'Bděte tedy, protože neznáte den ani hodinu.“',
        14: '„ Je to totiž jako s člověkem, který se chystal odcestovat: zavolal své otroky a svěřil jim svůj majetek.',
        15: 'Jednomu dal pět talentů, druhému dva, třetímu jeden, každému podle jeho schopností, a ihned odcestoval.',
        16: 'Ten, který přijal pět talentů, šel a vložil je do obchodu, a získal jiných pět.',
        17: 'Stejně [i] ten, který dostal dva, získal jiné dva.',
        18: 'Ale ten, který dostal jeden, odešel, vykopal ⌈v zemi jámu ⌉ a ukryl peníze svého pána.',
        19: 'Po dlouhé době pak přišel pán oněch otroků a začal s nimi účtovat.',
        20: 'Přistoupil ten, který dostal pět talentů, přinesl jiných pět talentů a řekl: Pane, pět talentů jsi mi svěřil; hle, jiných pět talentů jsem [jimi] získal.',
        21: 'Jeho pán mu řekl: Dobře, otroku dobrý a věrný, byl jsi věrný nad málem, ustanovím tě nad mnohým; vejdi v radost svého pána.',
        22: 'Přistoupil také ten, [který dostal] dva talenty a řekl: Pane, dva talenty jsi mi svěřil; hle, jiné dva talenty jsem získal.',
        23: 'Jeho pán mu řekl: Dobře, otroku dobrý a věrný, byl jsi věrný nad málem, ustanovím tě nad mnohým; vejdi v radost svého pána.',
        24: 'Přistoupil pak i ten, který dostal jeden talent, a řekl: Pane, poznal jsem, že jsi tvrdý člověk; sklízíš, kde jsi nezasel, a shromažďuješ, kde jsi nerozsypal.',
        25: 'Dostal jsem strach, odešel jsem a ukryl tvůj talent v zemi. Hle, zde máš, co je tvoje.',
        26: 'Jeho pán mu odpověděl: Zlý a lenivý otroku, věděl jsi, že sklízím, kde jsem nezasel, a shromažďuji, kde jsem nerozsypal?',
        27: 'Měl jsi tedy mé peníze dát směnárníkům, a já bych si ⌈po návratu⌉ vzal, co je moje, i s úrokem.',
        28: 'Vezměte tedy od něho ten talent a dejte tomu, který má deset talentů!',
        29: 'Neboť každému, kdo má, bude dáno a bude mít hojnost. Tomu, kdo nemá, však bude odňato i to, co má.',
        30: 'A toho neužitečného otroka vyhoďte do nejzazší temnoty. Tam bude pláč a skřípění zubů. “',
        31: '„Až přijde Syn člověka ve své slávě a všichni [svatí] andělé s ním, tehdy se posadí na trůn své slávy;',
        32: 'a budou před něj shromážděny všecky národy. A oddělí jedny od druhých, jako pastýř odděluje ovce od kozlů.',
        33: 'Ovce postaví po své pravici, kozly po levici.',
        34: 'Potom řekne Král těm po své pravici: Pojďte, požehnaní mého Otce, přijměte do dědictví království, které je pro vás připraveno od založení světa.',
        35: 'Neboť jsem hladověl a dali jste mi najíst, žíznil jsem a dali jste mi napít, byl jsem cizincem a ujali jste se mě,',
        36: 'byl jsem nahý a oblékli jste mě, byl jsem nemocen a navštívili jste mě, byl jsem ve vězení a přišli jste za mnou.',
        37: 'Tehdy mu spravedliví odpovědí: Pane, kdy jsme tě spatřili hladového a dali jsme ti najíst, nebo žíznivého a dali jsme ti napít?',
        38: 'Kdy jsme tě spatřili jako cizince a ujali jsme se tě, nebo nahého a oblékli jsme tě?',
        39: 'Kdy jsme tě spatřili nemocného nebo ve vězení a přišli jsme za tebou?',
        40: 'Král jim odpoví: Amen, pravím vám, cokoliv jste učinili jednomu z těchto mých nejmenších bratří, mně jste učinili. “',
        41: '„Potom řekne i těm po levici: Jděte ode mne, prokletí, do věčného ohně, který je připraven pro Ďábla a jeho anděly!',
        42: 'Neboť jsem hladověl, a nedali jste mi najíst, žíznil jsem, a nedali jste mi napít,',
        43: 'byl jsem cizincem, a neujali jste se mne, byl jsem nahý, a neoblékli jste mne, byl jsem nemocný a ve vězení, a nenavštívili jste mne.',
        44: 'Tu mu odpovědí i oni: Pane, kdy jsme tě spatřili hladového, žíznivého, jako cizince, nahého, nemocného nebo ve vězení, a neposloužili jsme ti?',
        45: 'Pak jim odpoví: Amen, pravím vám, cokoliv jste neučinili jednomu z těchto nejmenších, ani mně jste neučinili.',
        46: 'A tito půjdou do věčného trápení, ale spravedliví do věčného života.“',
    },
    26: {
        1: 'I stalo se, že když dokončil všechna tato slova, řekl Ježíš svým učedníkům:',
        2: '„Víte, že za dva dny bude ⌈Hod beránka⌉ a Syn člověka bude vydán, aby byl ukřižován.“',
        3: 'Tehdy se shromáždili velekněží a starší lidu ve dvoře velekněze, který se jmenoval Kaifáš,',
        4: 'a společně se poradili, jak by se lstí Ježíše zmocnili a zabili ho.',
        5: 'Říkali však: „Ne ve svátek, aby nenastalo pobouření mezi lidem.“',
        6: 'Když byl Ježíš v Betanii v domě Šimona Malomocného,',
        7: 'přistoupila k němu žena, která měla alabastrovou nádobku drahocenného oleje, a když byl u stolu, vylila mu ji na hlavu.',
        8: 'Když to [jeho] učedníci uviděli, rozhořčili se a řekli: „K čemu tato ztráta?',
        9: 'Vždyť se to mohlo draze prodat a peníze dát chudým.“',
        10: 'Ježíš to poznal a řekl jim: „Proč působíte té ženě těžkosti? Vykonala na mně dobrý skutek.',
        11: 'Vždyť chudé máte stále s sebou, mne však nemáte stále.',
        12: 'Když ona vylila tento olej na mé tělo, učinila to k mému pohřbu.',
        13: 'Amen, pravím vám, kdekoli po celém světě bude hlásáno toto evangelium, bude se na její památku mluvit také o tom, co ona učinila.“',
        14: 'Potom jeden ze Dvanácti, který se jmenoval Juda Iškariotský, šel k velekněžím',
        15: 'a řekl: „Co jste ochotni mi dát, když vám ho vydám?“A oni mu odvážili třicet stříbrných.',
        16: 'Od té chvíle hledal vhodnou příležitost, aby jim ho vydal.',
        17: 'Prvního dne svátku nekvašených chlebů přistoupili učedníci k Ježíšovi a řekli: „Kde chceš, abychom ti připravili k jídlu ⌈velikonočního beránka⌉?“',
        18: 'On pak řekl: „Jděte do města k jistému člověku a řekněte mu: Učitel říká: Můj čas je blízko. Budu u tebe se svými učedníky slavit velikonočního beránka. “',
        19: 'A učedníci učinili, jak jim Ježíš nařídil, a připravili velikonočního beránka.',
        20: 'Když nastal večer, stoloval s Dvanácti [učedníky].',
        21: 'A když jedli, řekl: „Amen, pravím vám, že jeden z vás mě zradí.“',
        22: 'Velmi se rmoutili a jeden každý [z nich] [mu] začal říkat: „Jsem to snad já, Pane?“',
        23: 'On odpověděl: „Kdo se mnou namočil ruku v míse, ten mě zradí.',
        24: 'Syn člověka sice odchází, jak je o něm napsáno, ale běda tomu člověku, skrze něhož bude Syn člověka zrazen. ⌈Pro toho by bylo lépe, kdyby se⌉ nenarodil!“',
        25: 'Juda, který ho zrazoval, ⌈na to⌉ řekl: „Jsem to snad já, Rabbi?“[Ježíš] mu odpověděl: „Tys to řekl.“',
        26: 'Když jedli, vzal Ježíš chléb, požehnal, rozlomil ho, dal učedníkům a řekl: „Vezměte, jezte. Toto je mé tělo.“',
        27: 'Pak vzal kalich, vzdal díky a dal jim ho ⌈se slovy⌉: „Napijte se z něho všichni.',
        28: 'Neboť toto je má krev [nové] smlouvy, která se vylévá za mnohé na odpuštění hříchů.',
        29: 'Pravím vám, [že] od této chvíle již nebudu pít z tohoto plodu vinné révy až do toho dne, kdy jej budu pít s vámi nový v království svého Otce.“',
        30: 'A zazpívali chvalozpěv a vyšli na Olivovou horu.',
        31: 'Tehdy jim Ježíš řekl: „Vy všichni ode mne této noci odpadnete, neboť je napsáno: Budu bít pastýře a ovce stáda se rozptýlí.',
        32: 'Ale po svém vzkříšení vás předejdu do Galileje.“',
        33: '⌈Na to⌉ mu Petr řekl: „Kdyby všichni od tebe odpadli, já nikdy neodpadnu!“',
        34: 'Ježíš mu řekl: „Amen, pravím tobě, že mě této noci, dřív než kohout zakokrhá, třikrát zapřeš.“',
        35: 'Petr mu řekl: „I kdybych měl s tebou zemřít, určitě tě nezapřu.“Podobně mluvili i ostatní učedníci.',
        36: 'Tehdy s nimi Ježíš přišel na místo zvané Getsemane a řekl učedníkům: „Posaďte se zde, zatímco se tamhle odejdu pomodlit.“',
        37: 'Vzal s sebou Petra a oba Zebedeovy syny; tu se začal rmoutit a znepokojovat.',
        38: 'Pak jim řekl: „Má duše je smutná až k smrti. Zůstaňte zde a bděte se mnou.“',
        39: 'A trochu poodešel, padl na tvář, modlil se a říkal: „Můj Otče, je–li to možné, ať mne mine tento kalich. Avšak ne jak já chci, ale jak chceš ty.“',
        40: 'Potom přišel k učedníkům a nalezl je spící, i řekl Petrovi: „To jste se mnou nemohli bdít jedinou hodinu?',
        41: 'Bděte a modlete se, abyste nevešli do pokušení. Duch je sice ochotný, ale tělo slabé.“',
        42: 'Opět podruhé odešel a pomodlil se, říkaje: „Můj Otče, není–li možné, aby [mne] tento [kalich] minul, musím–li ho vypít, staň se tvá vůle.“',
        43: 'Pak šel a nalezl je opět spící, protože měli velmi těžká víčka.',
        44: 'I nechal je, znovu odešel a pomodlil se potřetí, říkaje [opět] stejnou prosbu.',
        45: 'Tehdy přišel ke [svým] učedníkům a řekl jim: „⌈Ještě spíte a odpočíváte?⌉ Hle, přiblížila se ta hodina a Syn člověka je vydáván do rukou hříšníků.',
        46: 'Vstávejte, pojďme! Hle, přiblížil se ten, který mne zrazuje.“',
        47: 'Když ještě mluvil, hle, přišel Juda, jeden z Dvanácti, a s ním veliký zástup od velekněží a starších lidu s meči a holemi.',
        48: 'Ten, který ho zrazoval, ⌈s nimi domluvil znamení⌉: „Je to ten, kterého políbím; toho se zmocněte.“',
        49: 'A hned přistoupil k Ježíšovi a řekl: „Buď zdráv, Rabbi,“a vroucně ho políbil.',
        50: 'Ježíš mu řekl: „Příteli, proč jsi přišel?“Tu přistoupili, vztáhli na Ježíše ruce a zmocnili se ho.',
        51: 'A hle, jeden z těch, kteří byli s Ježíšem, natáhl ruku, vytasil meč, udeřil veleknězova otroka a uťal mu ucho.',
        52: 'Tehdy mu Ježíš řekl: „Vrať svůj meč na místo. Neboť všichni, kdo se chápou meče, mečem zahynou.',
        53: 'Či myslíš, že nemohu poprosit svého Otce, a on mi hned pošle víc než dvanáct legií andělů?',
        54: 'Jak by se však naplnila Písma, že se tak musí stát?“',
        55: 'V onu hodinu řekl Ježíš zástupům: „Jako na lupiče jste vyšli s meči a holemi, abyste mě zatkli. Den co den jsem sedával v chrámě a učil, a nezmocnili jste se mne.',
        56: 'Toto všechno se však stalo, aby se naplnila Písma proroků.“A v té chvíli ho všichni učedníci opustili a utekli.',
        57: 'Ti, kdo se Ježíše zmocnili, ho odvedli k veleknězi Kaifášovi, kde se shromáždili učitelé Zákona a starší.',
        58: 'Petr šel zpovzdálí za ním až k veleknězovu dvoru; vešel dovnitř a seděl se služebníky, aby uviděl konec.',
        59: 'Velekněží, [starší] a celá velerada hledali proti Ježíšovi křivé svědectví, aby ho mohli odsoudit k smrti,',
        60: 'ale nenašli, ačkoli předstoupilo mnoho křivých svědků. Nakonec předstoupili dva [křiví svědkové]',
        61: 'a řekli: „Tento člověk říkal: Mohu zbořit Boží svatyni a ve třech dnech [ji] vybudovat.“',
        62: 'Tu velekněz povstal a řekl mu: „Nic neodpovídáš? Co tito lidé svědčí proti tobě?“',
        63: 'Ježíš však mlčel. Velekněz mu řekl: „Zapřísahám tě při živém Bohu, abys nám řekl, zda jsi Mesiáš, Syn Boží!“',
        64: 'Ježíš mu říká: „Tys to řekl. Avšak pravím vám, od nynějška spatříte Syna člověka sedícího po pravici Moci a přicházejícího na nebeských oblacích.“',
        65: 'Tu velekněz roztrhl svá roucha a řekl: „Rouhal se! Nač ještě potřebujeme svědky? Hle, teď jste slyšeli rouhání.',
        66: 'Co si o tom myslíte?“Oni odpověděli: „Je hoden smrti.“',
        67: 'Pak mu naplivali do tváře a ztloukli ho pěstmi; někteří ho uhodili',
        68: 'a říkali: „Prorokuj nám, Mesiáši, kdo je ten, který tě udeřil?“',
        69: 'Petr seděl venku na dvoře. Přistoupila k němu jedna služka a řekla: „Také ty jsi byl s Ježíšem Galilejským!“',
        70: 'Ale on to přede všemi zapřel, říkaje: „Nevím, o čem mluvíš.“',
        71: 'A když [on] vyšel k bráně, spatřila ho jiná a řekla těm, kdo tam byli: „[I] tenhle byl s Ježíšem Nazaretským.“',
        72: 'A on opět zapřel s přísahou: „Neznám toho člověka.“',
        73: 'Za chvilku přistoupili ti, kteří tam stáli, a řekli Petrovi: „Skutečně i ty jsi z nich, vždyť i tvá řeč tě prozrazuje!“',
        74: 'Tehdy se začal zaklínat a zapřísahat: „Neznám toho člověka!“A hned nato zakokrhal kohout.',
        75: 'Tu si Petr vzpomněl na Ježíšovo slovo, jak řekl: Dříve než kohout zakokrhá, třikrát mne zapřeš. I vyšel ven a hořce se rozplakal.',
    },
    27: {
        1: 'Když nastalo ráno, uradili se všichni velekněží a starší lidu proti Ježíšovi, že ho usmrtí.',
        2: 'Spoutali ho, odvedli a vydali vladaři [Pontiu] Pilátovi.',
        3: 'Když ⌈jeho zrádce Juda⌉ uviděl, že byl Ježíš odsouzen, pocítil lítost a vrátil třicet stříbrných velekněžím a starším,',
        4: 'říkaje: „Zhřešil jsem, zradil jsem nevinnou krev!“Oni však řekli: „Co je nám po tom? ⌈To je tvoje věc⌉!“',
        5: 'Tu pohodil ty stříbrné ⌈do svatyně⌉ a vzdálil se; pak odešel a oběsil se.',
        6: 'Velekněží vzali ty stříbrné a řekli: „Není dovoleno v hodit je do chrámové pokladny, protože je to cena za krev.“',
        7: 'Uradili se a koupili za ně hrnčířovo pole k pohřbívání cizinců.',
        8: 'Proto je ono pole až dodnes nazýváno Polem krve.',
        9: 'Tehdy se naplnilo, co bylo řečeno skrze proroka Jeremjáše: I vzali třicet stříbrných, cenu Oceněného, který byl oceněn od synů Izraele;',
        10: 'a dali je za hrnčířovo pole, jak mi nařídil Pán.',
        11: 'Ježíš byl postaven před vladaře. Vladař se ho otázal: „Ty jsi král Židů?“Ježíš [mu] řekl: „Ty to říkáš.“',
        12: 'A když ho velekněží a starší obviňovali, nic neodpověděl.',
        13: 'Tu mu Pilát řekl: „Neslyšíš, co všechno proti tobě vypovídají?“',
        14: 'Ale on mu neodpověděl ani na jedno obvinění, takže se vladař velmi divil.',
        15: 'O svátcích měl vladař ve zvyku propouštět zástupu jednoho vězně, kterého chtěli.',
        16: 'Tehdy tam měli významného vězně, který se jmenoval Barabáš.',
        17: 'Když se tedy lidé shromáždili, řekl jim Pilát: „Koho chcete, abych vám propustil, Barabáše, nebo Ježíše, zvaného Kristus?“',
        18: 'Věděl totiž, že ho vydali ze závisti.',
        19: 'Když seděl na soudní stolici, ⌈vzkázala mu jeho žena⌉: „Neměj nic s tím spravedlivým, neboť jsem dnes kvůli němu ve snu mnoho vytrpěla.“',
        20: 'Velekněží a starší přesvědčili zástupy, aby si vyžádaly Barabáše, ale Ježíše aby daly zahubit.',
        21: 'Vladař jim tedy řekl: „Kterého z těch dvou chcete, abych vám propustil?“Oni řekli: „Barabáše!“',
        22: 'Pilát jim řekl: „Co tedy ⌈mám udělat⌉ s Ježíšem, zvaným Kristus?“Všichni [mu] řekli: „Ať je ukřižován!“',
        23: 'A [vládce] řekl: „Co tedy udělal zlého?“Oni však ještě víc křičeli: „Ať je ukřižován!“',
        24: 'Když Pilát uviděl, že to ničemu neprospívá, ale že pozdvižení je čím dál větší, vzal vodu, umyl si před zástupem ruce a řekl: „Jsem nevinen ⌈touto krví⌉. Je to vaše věc.“',
        25: 'A všechen lid na to řekl: „Jeho krev na nás a na naše děti!“',
        26: 'Pak jim propustil Barabáše. Ježíše dal zbičovat a vydal ho, aby byl ukřižován.',
        27: 'Tehdy vladařovi vojáci vzali Ježíše do ⌈vládního paláce⌉ a shromáždili k němu celý oddíl vojska.',
        28: 'Svlékli ho a oblékli mu šarlatový plášť,',
        29: 'upletli věnec z trní a vložili jej na jeho hlavu a do pravé ruky mu dali rákos ovou hůl. Padali před ním na kolena a posmívali se mu: „Buď zdráv, králi Židů!“',
        30: 'A když ho poplivali, vzali tu hůl a začali ho bít po hlavě.',
        31: 'Když se mu naposmívali, svlékli mu plášť a oblékli mu jeho šaty. A odvedli ho, aby ho ukřižovali.',
        32: 'Když vycházeli, potkali jednoho člověka z Kyrény, jménem Šimon; toho přinutili, aby vzal jeho kříž.',
        33: 'Když přišli na místo zvané Golgota, což znamená Místo lebky,',
        34: 'dali Ježíšovi pít víno smíchané se žlučí. Okusil, ale nechtěl pít.',
        35: 'Ukřižovali ho a rozdělili si jeho šaty házejíce o ně los;',
        36: 'pak seděli a střežili ho tam.',
        37: 'Nad hlavu mu dali ⌈nápis o jeho provinění⌉: „Toto je Ježíš, král Židů.“',
        38: 'Zároveň s ním byli ukřižováni dva lupiči, jeden po pravici a druhý po levici.',
        39: 'Kolemjdoucí ho uráželi, potřásali hlavou',
        40: 'a říkali: „Ty, který boříš svatyni a ve třech dnech ji stavíš, zachraň se, jsi–li Syn Boží, [a] sestup s kříže!“',
        41: 'Podobně se posmívali i velekněží s učiteli Zákona a staršími. Říkali:',
        42: '„Jiné zachránil, sám sebe zachránit nemůže. Je králem Izraele, ať nyní sestoupí s kříže, a my v něho uvěříme.',
        43: 'Složil naději v Bohu, ať [ho] nyní vysvobodí, ⌈stojí–li o něho⌉. Vždyť řekl: Jsem Boží Syn! “',
        44: 'Stejně ho tupili i lupiči, kteří byli ukřižováni spolu s ním.',
        45: 'Od šesté hodiny nastala tma po celé zemi až do hodiny deváté.',
        46: 'Kolem deváté hodiny zvolal Ježíš silným hlasem: „Eli, Eli, lema sabachthani?“To jest: Můj Bože, můj Bože, proč jsi mne opustil?',
        47: 'A když to uslyšeli někteří z těch, kdo tam stáli, říkali: „Ten člověk volá Eliáše.“',
        48: 'Jeden z nich ihned vyběhl, vzal houbu, naplnil ji octem, připevnil na rákos ovou hůl a dával mu pít.',
        49: 'Ostatní však říkali: „Nech ho, ať uvidíme, jestli přijde Eliáš a zachrání ho!“',
        50: 'Ale Ježíš znovu vykřikl silným hlasem a vypustil ducha.',
        51: 'A hle, opona svatyně se roztrhla ve dví odshora až dolů a země se zatřásla a skály se roztrhly',
        52: 'a hroby se otevřely a mnohá těla zesnulých svatých byla vzkříšena;',
        53: 'když vyšli z hrobů po jeho vzkříšení, vstoupili do svatého města a ukázali se mnohým.',
        54: 'Když setník a ti, kdo s ním střežili Ježíše, uviděli zemětřesení a to, co se stalo, velmi se ulekli a řekli: „Opravdu to byl Boží Syn!“',
        55: 'Bylo tam mnoho žen dívajících se zdaleka, které se vydaly za Ježíšem z Galileje a sloužily mu.',
        56: 'Mezi nimi byla Marie Magdalská, Marie, matka Jakubova a Josefova, a matka synů Zebedeových.',
        57: 'Když nastal večer, přišel bohatý člověk z Arimatie, jménem Josef, který se také sám stal Ježíšovým učedníkem.',
        58: 'Ten přišel k Pilátovi a požádal o Ježíšovo tělo. Tehdy Pilát rozkázal, aby mu [to tělo] vydali.',
        59: 'Josef tělo vzal, zavinul je do čistého plátna',
        60: 'a položil [je] do své nové hrobky, kterou vytesal ve skále. Pak ke vchodu do hrobky přivalil veliký kámen a odešel.',
        61: 'Byla tam Marie Magdalská a ta druhá Marie a seděly naproti hrobu.',
        62: 'Nazítří, to je po přípravě na svátek, se u Piláta shromáždili velekněží a farizeové',
        63: 'a řekli: „Pane, vzpomněli jsme si, že onen svůdce ještě za svého života řekl: Po třech dnech vstanu.',
        64: 'Rozkaž tedy, ať je do třetího dne hrob zajištěn, aby nepřišli [jeho] učedníci, neukradli ho a neřekli lidu: Vstal z mrtvých. A bude poslední blud horší než ten první.“',
        65: 'Pilát jim řekl: „Máte stráž. Jděte a zabezpečte to, jak umíte.“',
        66: 'Oni pak šli a zabezpečili hrob ⌈tak, že zapečetili kámen a postavili k němu stráž⌉.',
    },
    28: {
        1: 'Po sobotě, když už svítalo na první den týdne, přišla Marie Magdalská a ta druhá Marie, aby se podívaly na hrob.',
        2: 'A hle, nastalo veliké zemětřesení, neboť Pánův anděl sestoupil z nebe, přistoupil, odvalil kámen a posadil se na něm.',
        3: 'Jeho vzhled byl jako blesk a jeho roucho bílé jako sníh.',
        4: 'Strachem z něho se strážci roztřásli a zůstali jako mrtví.',
        5: 'Anděl promluvil k ženám: „Vy se nebojte. Vždyť vím, že hledáte Ježíše, toho ukřižovaného.',
        6: 'Není zde, neboť byl vzkříšen, jak řekl. Pojďte a podívejte se na místo, kde ležel [Pán].',
        7: 'A rychle jděte a povězte jeho učedníkům, že byl vzkříšen [z mrtvých]; a hle, jde před vámi do Galileje, tam ho spatříte. Hle, řekl jsem vám to.“',
        8: 'Rychle odešly od hrobky a se strachem i velikou radostí to běžely oznámit jeho učedníkům.',
        9: 'A [jak šly dát zprávu jeho učedníkům,] hle, Ježíš je potkal a řekl: „Buďte pozdraveny!“Ony přistoupily, objaly mu nohy a poklonily se mu.',
        10: 'Tehdy jim Ježíš řekl: „Nebojte se! Jděte a oznamte mým bratřím, aby odešli do Galileje; tam mě uvidí.“',
        11: 'Když ženy odcházely, hle, někteří ze stráže přišli do města a oznámili velekněžím všechno, co se přihodilo.',
        12: 'Ti se shromáždili se staršími, poradili se a dali vojákům hodně peněz',
        13: '⌈se slovy⌉: „Řekněte: Jeho učedníci přišli v noci, a když jsme spali, ho ukradli.',
        14: 'Doslechne–li se o tom vladař, my [ho] uchlácholíme a vás zbavíme starostí.“',
        15: 'Oni vzali peníze a učinili, jak byli poučeni. A ⌈tato zpráva je mezi Židy rozšířena⌉ až do dnešního dne.',
        16: 'Jedenáct učedníků odešlo do Galileje na horu, kterou jim Ježíš určil.',
        17: 'Když ho spatřili, poklonili se [mu]; ale někteří pochybovali.',
        18: 'Ježíš přistoupil a promluvil k nim: „Byla mi dána veškerá pravomoc na nebi i na zemi.',
        19: 'Jděte [tedy] a čiňte učedníky ze všech národů, křtěte je ve jméno Otce i Syna i Ducha Svatého',
        20: 'a učte je zachovávat všechno, co jsem vám přikázal. A hle, já jsem s vámi po všechny dny až do skonání tohoto věku. [Amen.]“',
    },
}
